const BLOCKS=[{value:'title',label:'Título'},{value:'paragraph',label:'Párrafo'},{value:'list',label:'Lista'},{value:'image',label:'Imagen'},{value:'button',label:'Botón / enlace'},{value:'link',label:'Enlace de texto'},{value:'divider',label:'Separador'}];
