function blockEditor(blocks,root){let target=root.querySelector('#blocks');function sync(){target.querySelectorAll('[data-block]').forEach((el,i)=>{blocks[i].type=el.querySelector('[data-type]').value;blocks[i].text=el.querySelector('[data-text]').value;blocks[i].url=el.querySelector('[data-url]').value})}function draw(){target.innerHTML=blocks.map((b,i)=>`<div class="sub" data-block><div class="row"><b>Bloque ${i+1}</b><div class="actions"><button type="button" data-bmove="${i},-1">↑</button><button type="button" data-bmove="${i},1">↓</button><button type="button" data-bdel="${i}" class="danger">Eliminar</button></div></div><label>Tipo</label><select data-type>${BLOCKS.map(o=>`<option value="${o.value}" ${o.value===b.type?'selected':''}>${o.label}</option>`).join('')}</select><label>Texto / título / elementos (una línea por elemento)</label><textarea data-text>${E(b.text)}</textarea><div class="field imagefield"><label>URL (imagen, botón o enlace)</label><input data-url value="${E(b.url)}"><input type="file" accept="image/png,image/jpeg,image/webp,image/gif" data-image="block_${i}">${b.type==='image'?imageHTML(b.url):''}</div></div>`).join('');bindImages(target);target.querySelectorAll('[data-bmove]').forEach(b=>b.onclick=()=>{sync();let [i,d]=b.dataset.bmove.split(',').map(Number);move(blocks,i,d);draw()});target.querySelectorAll('[data-bdel]').forEach(b=>b.onclick=()=>{sync();blocks.splice(+b.dataset.bdel,1);draw()})}root.querySelector('#addblock').onclick=()=>{sync();blocks.push({type:'paragraph',text:'',url:''});draw()};draw();return sync}
