function suggestEdit(id){if(id)return toast('Las sugerencias publicadas no se editan.');let s=record('suggestions',id);if(s?!(s.owner===me.id&&allow('suggestions','edit')||allow('suggestions','manage')):!allow('suggestions','create'))return;if(!s&&!withinLimit('suggestions'))return;dialog(s?'Editar sugerencia':'Nueva sugerencia',field('Tipo','type','select',s?.type||'Rol',true,['Rol','Discord','Web'])+field('Título','title','text',s?.title||'',true)+field('Propuesta','body','textarea',s?.body||'',true)+field('Imagen','image','image',s?.image||'')+(s&&reasonNeeded('suggestions',s)?reasonField():''),f=>{let n={...s,id:s?.id||uid(),owner:s?.owner||me.id,created:s?.created||now(),status:s?.status||initialState('suggestions'),votes:s?.votes||{},comments:s?.comments||[],type:f.type,title:f.title,body:f.body,image:f.image};mutate(['records','suggestions'],a=>s?a.splice(a.findIndex(x=>x.id===id),1,n):a.push(n),'Sugerencia: '+n.title,auditReason(f))})}
