function eventEdit(k,id){if(!requirePerm(k,'manage'))return;let r=record(k,id);if(!r&&!withinLimit(k))return;dialog(r?'Editar':'Crear '+NAMES[k],field('Título','title','text',r?.title||'',true)+field('Descripción','body','textarea',r?.body||'',true)+field('Imagen','image','image',r?.image||'')+field('Fecha de cierre (opcional)','end','datetime-local',r?.end?r.end.slice(0,16):'')+(k==='polls'?field('Opciones (una por línea)','options','textarea',(r?.options||[]).join('\n'),true):field('Cantidad de ganadores','count','number',r?.count||1,true)+field('Zenis por ganador (0 = sin premio monetario)','zenis','number',r?.zenis||0,true)+field('Acceso a raza exclusiva (opcional)','raceReward','select',r?.raceReward||'',false,op(db.records.raceDefinitions.filter(x=>x.exclusive))))+reasonField(),f=>{let options=f.options?.split('\n').map(s=>s.trim()).filter(Boolean)||[];if(k==='polls'&&options.length<2)throw Error('Añade al menos dos opciones.');if(k==='draws'&&(!Number.isInteger(+f.count)||+f.count<1||!Number.isFinite(+f.zenis)||+f.zenis<0))throw Error('Cantidad inválida.');if(r&&Object.keys(r.votes||{}).length&&JSON.stringify(options)!==JSON.stringify(r.options))throw Error('No se pueden cambiar opciones con votos existentes.');let n={...r,id:r?.id||uid(),owner:r?.owner||me.id,created:r?.created||now(),title:f.title,body:f.body,image:f.image,end:f.end?new Date(f.end).toISOString():'',options,count:+f.count||1,zenis:+f.zenis||0,raceReward:f.raceReward||'',votes:r?.votes||{},entries:r?.entries||[],winners:r?.winners||[],closed:r?.closed||false};mutate(['records',k],a=>r?a.splice(a.findIndex(x=>x.id===id),1,n):a.push(n),`${r?'Edición':'Creación'} de ${NAMES[k]}: ${n.title}`,f.reason)})}function eventActive(r){return r&&!r.closed&&(!r.end||Date.now()<Date.parse(r.end))}function pollVote(id,i){let r=record('polls',id);if(!requirePerm('polls','vote')||!eventActive(r))return;if(!Number.isInteger(i)||i<0||i>=r.options.length)throw Error('Opción inválida.');mutate(['records','polls'],a=>{let v=a.find(x=>x.id===id).votes;if(v[me.id]===i)delete v[me.id];else v[me.id]=i},'Voto en encuesta '+r.title);render()}function drawJoin(id){let r=record('draws',id);if(!requirePerm('draws','vote')||!eventActive(r))return;mutate(['records','draws'],a=>{let e=a.find(x=>x.id===id).entries,i=e.indexOf(me.id);i<0?e.push(me.id):e.splice(i,1)},'Participación en sorteo '+r.title);render()}function eventClose(k,id){if(!requirePerm(k,'manage'))return;withReason('Cerrar '+NAMES[k],r=>mutate(['records',k],a=>a.find(x=>x.id===id).closed=true,'Cierre de '+NAMES[k],r))}function randomIndex(n){let a=new Uint32Array(1);crypto.getRandomValues(a);return Math.floor(a[0]/4294967296*n)}function drawWinners(id){if(!requirePerm('draws','manage'))return;let r=record('draws',id),eligible=r.entries.filter(id=>db.users.some(u=>u.id===id&&!u.disabled));if(eligible.length<r.count)return toast('No hay suficientes participantes activos.');if(r.winners.length)return;withReason('Realizar sorteo',reason=>transaction([['records','draws'],['users']],([draws,users])=>{let x=draws.find(x=>x.id===id),pool=[...eligible];x.winners=Array.from({length:x.count},()=>pool.splice(randomIndex(pool.length),1)[0]);x.closed=true;for(let id of x.winners){let u=users.find(u=>u.id===id);let reward=calc15('drawReward',{base:+x.zenis||0,participants:eligible.length,winners:x.count});x.awardedZenis=reward;u.balance+=reward;if(x.raceReward){u.raceAccess??=[];if(!u.raceAccess.includes(x.raceReward))u.raceAccess.push(x.raceReward)}}},'Ganadores y premios de '+r.title,reason))}
function base_walletPage(){return head('Zenis e inventario','Saldos y objetos registrados.')+`<div class="card"><small>Tu saldo</small><div class="number">${me.balance} ${E(db.settings.currency)}</div></div><div class="card"><h2>Tu inventario</h2>${table(['Objeto','Cantidad'],me.inventory.map(x=>[E(x.name),E(x.qty)]))}</div>`+(allow('wallet','manage')?`<div class="card"><h2>Gestión de saldos e inventarios</h2>${table(['Usuario','Saldo','Objetos','Acciones'],db.users.map(u=>[E(u.name),E(u.balance),E(u.inventory.reduce((a,x)=>a+x.qty,0)),btn('Modificar saldo','balance',[u.id])+btn('Inventario','inventory',[u.id])]))}</div>`:'')}
function balance(id){if(!requirePerm('wallet','manage'))return;let u=db.users.find(x=>x.id===id);dialog('Modificar saldo de '+u.name,field('Operación','op','select','sum',true,[{value:'sum',label:'Añadir'},{value:'sub',label:'Retirar'},{value:'set',label:'Establecer'}])+field('Cantidad','amount','number',0,true)+reasonField(),f=>{let n=+f.amount;if(!Number.isFinite(n)||n<0)throw Error('Cantidad inválida.');let val=f.op==='set'?n:f.op==='sum'?u.balance+n:u.balance-n;if(val<0)throw Error('Saldo insuficiente.');mutate(['users'],a=>a.find(x=>x.id===id).balance=val,'Saldo de usuario #'+id,f.reason)})}
function addItem(u,name,qty){let i=u.inventory.find(x=>x.name===name);if(i){i.qty+=qty;if(i.qty<=0)u.inventory=u.inventory.filter(x=>x!==i)}else if(qty>0)u.inventory.push({name,qty})}function inventory(id){if(!requirePerm('wallet','manage'))return;let u=db.users.find(x=>x.id===id);dialog('Inventario de '+u.name,table(['Objeto','Cantidad'],u.inventory.map(x=>[E(x.name),E(x.qty)]))+field('Nombre exacto del objeto','name','text','',true)+field('Variación de cantidad (+ añadir / − retirar)','qty','number',1,true)+reasonField(),f=>{let q=+f.qty;if(!Number.isInteger(q)||q===0)throw Error('Cantidad inválida.');if(q<0&&(u.inventory.find(x=>x.name===f.name)?.qty||0)<-q)throw Error('No hay suficientes objetos.');mutate(['users'],a=>addItem(a.find(x=>x.id===id),f.name,q),'Inventario de usuario #'+id,f.reason)})}
function base_transaction(paths,fn,action,reason=''){let before=paths.map(p=>clone(target(p))),after=clone(before);fn(after);let entry={id:uid(),at:now(),actor:actor(),action,paths,before,after:clone(after),reason,reversible:true};paths.forEach((p,i)=>setpath(p,after[i]));db.logs.unshift(entry);if(!paths.some(p=>p[0]==='settings'))db.settings.consumption.write+=paths.length;if(!save()){paths.forEach((p,i)=>setpath(p,before[i]));db.logs.shift();return false}return true}function buy(id){if(!requirePerm('shop','execute'))return;let p=record('shop',id),sheets=db.records.sheets.filter(s=>s.owner===me.id&&approved('sheets',s));if(!sheets.length)return toast('Necesitas una ficha aprobada.');dialog('Comprar '+p.name,field('Personaje','sheet','select','',true,op(sheets.map(s=>({...s,name:recordName('sheets',s)}))))+field('Cantidad','qty','number',1,true)+`<p>Precio unitario: ${price(p)} ${E(db.settings.currency)}</p>`,f=>{let q=+f.qty,s=record('sheets',f.sheet);if(!s||s.owner!==me.id||!approved('sheets',s))throw Error('Personaje no válido.');if(!Number.isInteger(q)||q<1)throw Error('Cantidad inválida.');if(p.stock!==-1&&p.stock<q)throw Error('No hay existencias suficientes.');if(me.balance<calc15('purchase',{unit:price(p),quantity:q}))throw Error('Saldo insuficiente.');return transaction([['users'],['records','shop'],['records','sheets']],([us,shop,sheets])=>{let u=us.find(x=>x.id===me.id),r=shop.find(x=>x.id===id),s=sheets.find(x=>x.id===f.sheet);u.balance-=calc15('purchase',{unit:price(r),quantity:q});s.inventory.push({item:r.id,name:r.name,rarity:'Tienda',qty:q,status:'Disponible',at:now()});if(r.stock!==-1)r.stock-=q},'Compra de '+q+' × '+p.name+' para '+recordName('sheets',s))})}
function spinPage(){let a=db.records.spin,total=a.reduce((s,x)=>s+x.weight,0);return head('Spin','Premios y probabilidades configurables.',permitted('spin','manage','Añadir premio','spinEdit',[null],'primary'))+`<div class="card"><p>Coste por tirada: ${db.settings.spinCost||0} ${E(db.settings.currency)}</p>${permitted('spin','execute','Girar','spinRoll',[],'primary')} ${permitted('spin','manage','Configurar coste','spinCost')}</div>`+table(['Premio','Peso','Probabilidad','Acciones'],a.map(r=>[E(r.name),E(r.weight),total?(100*r.weight/total).toFixed(2)+' %':'—',permitted('spin','manage','Editar','spinEdit',[r.id])+permitted('spin','manage','Eliminar','remove',['spin',r.id],'danger')]))}
