 function add(category,name,raceName,description='',initial=true){let rid=race(raceName)?.id,c=cat(category);if(!rid||!c||d.records.catalogs.some(x=>x.category===c&&x.name===name&&x.race===rid))return;d.records.catalogs.push({id:uid(),category:c,name,race:rid,initial,description,requirements:'',blocks:[],owner:0,created:now()})}
