function customRaceProtection(r){let proposal=r?.custom?record('races',r.custom):null;return proposal?.protected?proposal:null}
function raceSelectable(r,s){if(!r||r.unavailable||!r.variants.some(v=>v.cap!=null))return false;if(r.custom){let proposal=record('races',r.custom);if(!proposal||!approved('races',proposal))return false;}if(s&&val(s,'race')===r.id)return true;if(r.exclusive&&!me?.raceAccess?.includes(r.id))return false;let proposal=customRaceProtection(r);return !proposal||proposal.owner===me?.id||!!proposal.authorizedUsers?.includes(me?.id)}
function autoInitial(x,race){return !!race&&x.initial&&(x.autoInitial??(x.race===race.id))}function manualField(f){return ['Técnicas raciales','Técnicas','Transformaciones','Estilos','Controles','Estados de combate','Armas','Objetos','Cápsulas'].includes(f.key)||['Habilidades raciales','Técnicas de combate','Armas','Objetos especiales','Cápsulas','Transformaciones desbloqueadas','Estilos','Controles','Estados'].includes(f.label)}
function inCategory(entry,category){return !!category&&(entry.category===category.id||categoryName(entry.category).startsWith(categoryName(category.id)+' / '))}
function initialAllowed(x,race,category,variant){if(!race||!x.initial||x.unavailable||!inCategory(x,category)||x.race&&x.race!==race.id||x.variant&&x.variant!==variant?.id)return false;return true}
