function unlockedTransforms(s){let owned=new Set(db.schemas.sheets.flatMap(sec=>sec.fields).filter(f=>dataAllowed('sheets','f_'+f.id)).flatMap(f=>[s.values?.[f.id]].flat()).filter(x=>typeof x==='string'));if(!allow('catalogs')||!dataAllowed('catalogs','content'))return [];return db.records.catalogs.filter(x=>owned.has(x.id)&&isTransform(x)&&(!x.race||x.race===raceOf(s)?.id)&&STATS.every(k=>Number.isFinite(x.multipliers?.[k])&&x.multipliers[k]>0))}
