function simulatorSelect(){if(!requirePerm('compare','execute')||!comparisonDataAllowed())return;let a=record('sheets',$('[name=a]').value),b=record('sheets',$('[name=b]').value);if(!a||!b||a.id===b.id)return toast('Selecciona dos fichas distintas.');let options=s=>[{value:'base',label:'Forma base'},...op(unlockedTransforms(s))];$('#simoptions').innerHTML=`<div class="card"><h2>Simulación de transformaciones</h2><p class="muted">Solo se muestran formas desbloqueadas con multiplicadores configurados. Selecciona una por personaje.</p><div class="two">${field(recordName('sheets',a),'simA','select','base',true,options(a))}${field(recordName('sheets',b),'simB','select','base',true,options(b))}</div>${btn('Calcular','compare',[],'primary')}</div>`;compare()}
function simStats(s,input){let e=unlockedTransforms(s).find(x=>x.id===$('[name='+input+']')?.value);return {...Object.fromEntries(STATS.map(k=>[k,e?calc15('transformation',{base:+val(s,k)||0,multiplier:e.multipliers[k]??1}):(+val(s,k)||0)])),form:e?.name||'Base'}}
function sumStats(a){return power15(STATS.map(k=>a[k]))}
function conditionOptions(type){if(type==='stat')return [...STATS,'Poder de pelea','Magia'];if(type==='race')return op(db.records.raceDefinitions);if(type==='catalog')return op(db.records.catalogs);if(type==='item')return op([...db.records.catalogs,...db.records.shop]);if(type==='trust')return op(db.records.teachers);if(type==='talent')return db.settings.talents.map(t=>t.name);return []}
function conditionFailures(e,s){if(!e)return ['Entrada inexistente'];let issues=[];if(e.teacher&&(s.trust?.[e.teacher]||0)<e.trust)issues.push('Confianza insuficiente');if(e.race&&e.race!==raceOf(s)?.id)issues.push('Raza incompatible');for(let c of e.conditions||[]){let amount=+c.min;let passed=false;if(c.type==='stat'){let value=c.ref==='Poder de pelea'?power(s):c.ref==='Magia'?s.magic||0:+val(s,c.ref)||0;passed=c.op==='max'?value<=amount:value>=amount}else if(c.type==='race')passed=raceOf(s)?.id===c.ref;else if(c.type==='catalog')passed=ownedCatalog(s).has(c.ref);else if(c.type==='item')passed=(s.inventory||[]).filter(x=>x.item===c.ref).reduce((n,x)=>n+(+x.qty||0),0)>=amount;else if(c.type==='trust')passed=(s.trust?.[c.ref]||0)>=amount;else if(c.type==='talent')passed=s.potential===c.ref;if(!passed)issues.push(conditionLabel(c))}return issues}
function conditionLabel(c){let options=conditionOptions(c.type),opt=options.find(x=>(typeof x==='string'?x:x.value)===c.ref),name=typeof opt==='string'?opt:opt?.label||'Registro eliminado';return ({stat:'Estadística',race:'Raza',catalog:'Desbloqueo',item:'Objeto',trust:'Confianza',talent:'Talento'}[c.type]||c.type)+': '+name+(['stat','item','trust'].includes(c.type)?' '+(c.op==='max'?'≤':'≥')+' '+c.min+(c.type==='trust'?'%':''):'')}
function conditionsEdit(id){if(!requirePerm('catalogs','manage'))return;let r=record('catalogs',id),a=clone(r.conditions||[]),sync;let types=[{value:'stat',label:'Estadística / poder / magia'},{value:'race',label:'Raza'},{value:'catalog',label:'Técnica, transformación o entrada adquirida'},{value:'item',label:'Objeto en inventario'},{value:'trust',label:'Confianza con maestro'},{value:'talent',label:'Talento'}];dialog('Requisitos condicionales · '+r.name,'<p>Se deben cumplir todas las condiciones. El texto narrativo sigue requiriendo revisión del Staff.</p><div id="conditions"></div><button type="button" id="addcondition">Añadir condición</button>'+reasonField(),f=>{sync();if(a.some(c=>!c.ref||!conditionOptions(c.type).some(x=>(typeof x==='string'?x:x.value)===c.ref)||(['stat','trust','item'].includes(c.type)&&(!Number.isFinite(c.min)||c.min<0||c.type==='trust'&&c.min>100||c.type==='item'&&(!Number.isInteger(c.min)||c.min<1)))))throw Error('Revisa las condiciones.');return mutate(['records','catalogs'],b=>b.find(x=>x.id===id).conditions=a,'Requisitos de '+r.name,f.reason)},{wide:true,bind:root=>{let list=root.querySelector('#conditions');sync=()=>{list.querySelectorAll('[data-cond]').forEach((el,i)=>{a[i]={...a[i],type:el.querySelector('[name=ctype]').value,ref:el.querySelector('[name=cref]').value,op:el.querySelector('[name=cop]')?.value||'min',min:+(el.querySelector('[name=cmin]')?.value||0)}})};
 let paint=()=>{list.innerHTML=a.map((c,i)=>`<div class="sub" data-cond>${field('Tipo','ctype','select',c.type,true,types)}${field('Requisito','cref','select',c.ref,true,conditionOptions(c.type).filter(x=>(typeof x==='string'?x:x.value)!==id))}${c.type==='stat'?field('Comparación','cop','select',c.op,true,[{value:'min',label:'Mínimo (≥)'},{value:'max',label:'Máximo (≤)'}]):''}${['stat','trust','item'].includes(c.type)?field('Cantidad / umbral','cmin','number',c.min,true):''}<button type="button" data-removecond="${i}" class="danger">Eliminar condición</button></div>`).join('');list.querySelectorAll('[name=ctype]').forEach((el,i)=>el.onchange=()=>{sync();a[i].ref='';a[i].min=0;a[i].op='min';paint()});list.querySelectorAll('[data-removecond]').forEach(el=>el.onclick=()=>{sync();a.splice(+el.dataset.removecond,1);paint()})};root.querySelector('#addcondition').onclick=()=>{sync();a.push({type:'stat',ref:'',op:'min',min:0});paint()};paint()}})}
function checkConditions(id){let e=record('catalogs',id);if(!e||!allow('catalogs'))return;let a=db.records.sheets.filter(s=>s.owner===me.id||allow('sheets','manage'));show('Requisitos · '+e.name,`<p>${E(e.requirements||'Sin requisitos narrativos indicados.')}</p><div class="card">${(e.conditions||[]).map(c=>`<p>${E(conditionLabel(c))}</p>`).join('')||'<p class="muted">No hay condiciones adicionales.</p>'}</div>`+a.map(s=>{let failures=conditionFailures(e,s);return `<div class="sub"><b>${E(recordName('sheets',s))}</b><p class="${failures.length?'bad':'good'}">${failures.length?'No cumple: '+E(failures.join(' · ')):'Cumple las condiciones registradas'}</p></div>`}).join(''))}
// Human-readable audit display, including changes to nested data and historical records.
const AUDIT_LABELS={sagas:'Historial de sagas',sagaContext:'Reglas al presentar el informe',approvalSaga:'Reglas al aprobar el informe',sagaId:'Saga',sagaName:'Nombre de saga',started:'Inicio',ended:'Fin',revisions:'Versiones de reglas',revision:'Versión de reglas',methodSnapshot:'Método aplicado',locationSnapshot:'Lugar aplicado',variantBonus:'Bonificación racial',powerBefore:'Poder de pelea al registrar',id:'Identificador',owner:'Propietario',name:'Nombre',title:'Título',description:'Descripción',body:'Contenido',values:'Campos de la ficha',manual:'Descripciones manuales',status:'Estado',created:'Creación',updated:'Actualización',at:'Fecha',actor:'Autor',roles:'Roles',perms:'Permisos',balance:'Saldo / equilibrio',magic:'Magia',initialPower:'Poder inicial',variant:'Variante',potential:'Talento elegido',potentialChoices:'Resultados de talento',inventory:'Inventario',qty:'Cantidad',item:'Objeto',rarity:'Rareza',method:'Método',location:'Lugar',sheet:'Personaje',estimate:'Ganancia sugerida',awarded:'Ganancia concedida',reviewNote:'Nota de revisión',reason:'Motivo',category:'Categoría',fields:'Campos',options:'Opciones',label:'Etiqueta',required:'Obligatorio',teacher:'Maestro',trust:'Confianza',weight:'Probabilidad (%)',conditions:'Condiciones',multipliers:'Multiplicadores',before:'Antes',after:'Después',image:'Imagen',hash:'Contraseña protegida',salt:'Dato de seguridad protegido',exclusive:'Exclusiva',unavailable:'No disponible',trainingCount:'Entrenamientos',wins:'Victorias',losses:'Derrotas',applied:'Recompensa aplicada',cap:'Máximo inicial',bonus:'Bonificación',passwordMin:'Contraseña mínima',passwordMax:'Contraseña máxima',balanceEnabled:'Equilibrio activo',softCap:'Límite de estadísticas',divisor:'Divisor',market:'Mercado',rules:'Reglas del rol'};
function auditLabel(k){let f=Object.values(db.schemas).flatMap(s=>s.flatMap(g=>g.fields)).find(x=>x.id===k);return f?.label||AUDIT_LABELS[k]||NAMES[k]||String(k).replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,x=>x.toUpperCase())}
function auditRef(x,k){if(typeof x!=='string'&&typeof x!=='number')return null;let r=db.roles.find(r=>r.id===x)||db.categories.find(r=>r.id===x)||Object.values(db.states).flat().find(r=>r.id===x)||Object.values(db.records).flat().find(r=>r.id===x)||db.records.raceDefinitions.flatMap(r=>r.variants).find(v=>v.id===x);if(r)return r.name||r.title||(r.values?recordName(db.records.sheets.includes(r)?'sheets':'races',r):null);if(['owner','user','actor'].includes(k)&&db.users.some(u=>u.id===x))return userName(x);return null}
function auditValue(v,k=''){if(v===undefined||v===null||v==='')return '<span class="muted">Sin valor</span>';if(typeof v==='boolean')return v?'Sí':'No';if(typeof v==='string'&&/^data:image\//i.test(v))return imageHTML(v,'pic')||'Imagen';if(typeof v==='string'&&k.toLowerCase().includes('image')&&safeurl(v))return imageHTML(v,'pic')||E(v);if(Array.isArray(v))return v.length?`<ul>${v.map(x=>`<li>${auditValue(x,k)}</li>`).join('')}</ul>`:'<span class="muted">Vacío</span>';if(typeof v==='object'){let entries=Object.entries(v).filter(([key])=>!['hash','salt','password','id'].includes(key));return entries.length?`<dl>${entries.map(([key,value])=>`<dt>${E(auditLabel(key))}</dt><dd>${auditValue(value,key)}</dd>`).join('')}</dl>`:'<span class="muted">Sin datos adicionales</span>'}let ref=auditRef(v,k);if(ref)return E(ref);if(typeof v==='string'&&/^\d{4}-\d\d-\d\dT\d\d:/.test(v))return E(date(v));return E(typeof v==='number'?v.toLocaleString('es-ES'):v)}
function auditDiff(b,a,labels=[],key='',rows=[]){if(JSON.stringify(b)===JSON.stringify(a))return rows;if(['hash','salt','password'].includes(key))return rows;if(b&&a&&typeof b==='object'&&typeof a==='object'){if(Array.isArray(b)&&Array.isArray(a)){if([...b,...a].length&&[...b,...a].every(x=>x&&typeof x==='object'&&x.id!==undefined)){let ids=[...new Set([...b,...a].map(x=>x.id))];let oldOrder=b.filter(x=>a.some(y=>y.id===x.id)).map(x=>x.id),newOrder=a.filter(x=>b.some(y=>y.id===x.id)).map(x=>x.id);let title=x=>x?.name||x?.title||(x?.values?recordName('sheets',x):'Registro');if(JSON.stringify(oldOrder)!==JSON.stringify(newOrder))rows.push({labels:[...labels,'Orden'],b:b.map(title),a:a.map(title),key:'order'});for(let id of ids){let x=b.find(z=>z.id===id),y=a.find(z=>z.id===id);auditDiff(x,y,[...labels,title(y||x)],key,rows)}return rows}rows.push({labels,b,a,key});return rows}if(!Array.isArray(b)&&!Array.isArray(a)){for(let k of new Set([...Object.keys(b),...Object.keys(a)]))if(k!=='id')auditDiff(b[k],a[k],[...labels,auditLabel(k)],k,rows);return rows}}rows.push({labels,b,a,key});return rows}
function old14_auditView(id){let l=db.logs.find(x=>x.id===id);if(!l)return;let paths=l.paths||[l.path||[]],bs=l.paths?l.before:[l.before],as=l.paths?l.after:[l.after],rows=[];paths.forEach((p,i)=>auditDiff(redact(bs[i]),redact(as[i]),[p.map(k=>auditLabel(k)).join(' · ')],p.at(-1),rows));show(l.action,`<div class="card"><p><b>Autor:</b> ${E(l.actor.name)} · ${date(l.at)}</p><p><b>Motivo:</b> ${E(l.reason||'No requerido')}</p><p class="muted">${rows.length} cambios visibles · ${l.reversible?(canUndo(l)?'Reversible':'No reversible sin sobrescribir cambios posteriores'):'No reversible'}</p></div><div class="card">${rows.map(r=>`<div class="audit-row"><div><small>${E(r.labels.slice(0,-1).join(' › '))}</small><h4>${E(r.labels.at(-1)||'Valor')}</h4></div><div><small>Antes</small><div class="audit-value audit-before">${auditValue(r.b,r.key)}</div></div><div><small>Después</small><div class="audit-value audit-after">${auditValue(r.a,r.key)}</div></div></div>`).join('')||'<p class="muted">Sin cambios de datos visibles (los datos de seguridad se ocultan).</p>'}</div>`)}


// V5: chronological saga history; rules and reports are preserved independently of later changes.
function upgrade5(d){if(d.version>=5)return;upgrade4(d);d.version=5;d.records.sagas??=[];if(!d.menu.some(g=>g[1].some(x=>x[0]==='sagas'))){let g=d.menu.find(g=>g[1].some(x=>x[0]==='training'));if(g)g[1].splice(g[1].findIndex(x=>x[0]==='training')+1,0,['sagas','Historial de sagas']);else d.menu.push(['Personajes',[['sagas','Historial de sagas']]])}for(let r of d.roles.filter(r=>r.id!=='owner'))r.perms.sagas??={view:!!r.perms.training?.view,manage:false};}
function activeSaga(){return db.records.sagas?.find(x=>!x.ended)||null}
function sagaRules(r){return {softCap:r.softCap,divisor:r.divisor,balanceEnabled:!!r.balanceEnabled,balance:r.balance,thresholds:clone(r.thresholds||[])}}
function sagaRevision(r,reason=''){return {id:uid(),at:now(),actor:actor(),reason,rules:sagaRules(r)}}
function currentSagaContext(){let s=activeSaga();return {sagaId:s?.id||null,sagaName:s?.name||null,revision:s?.revisions.at(-1)?.id||null,rules:sagaRules(db.settings.rules)}}
function trainingSagaContext(s,m,l){return {...currentSagaContext(),powerBefore:power(s),variantBonus:variantOf(s)?.bonus||0,methodSnapshot:clone(m),locationSnapshot:clone(l),formula:db.settings.formulas?.training||DEFAULT_GAIN,formulaBase:db.settings.formulas?.trainingBase||FORMULAS15.trainingBase[2]}}
function sagaRuleSummary(r){if(!r)return 'Sin datos históricos';return `Umbral: ${E(r.softCap)} · Ganancias ÷${E(r.divisor)} al alcanzar el umbral · Equilibrio: ${r.balanceEnabled?'×'+E(r.balance):'desactivado'}`}
function trainingSagaHTML(r){let c=r.sagaContext,a=r.approvalSaga;return `<div class="sub"><b>Contexto histórico</b><p>${c?E(c.sagaName||'Sin saga activa al registrar'):'Informe anterior al historial de sagas'}</p>${c?`<p class="muted">${sagaRuleSummary(c.rules)}</p>`:''}${a?`<p>Validado el ${date(a.at)} · ${E(a.sagaName||'Sin saga activa')}</p><p class="muted">${sagaRuleSummary(a.rules)}</p>`:''}</div>`}
function sagasPage(){let a=activeSaga(),list=[...db.records.sagas].reverse();return head('Historial de sagas','Etapas del rol y reglas vigentes en cada momento.',permitted('sagas','manage','Iniciar saga','sagaStart',[],'primary'))+`<div class="card"><div class="row"><div><h2>${a?E(a.name):'Sin saga activa'}</h2><p>${sagaRuleSummary(sagaRules(db.settings.rules))}</p>${a?`<p class="muted">Desde ${date(a.started)}</p>`:''}</div>${a?permitted('sagas','manage','Finalizar saga','sagaFinish',[]):''}</div></div>`+(list.length?list.map(x=>{let reports=db.records.training.filter(r=>r.sagaContext?.sagaId===x.id);return `<div class="card"><div class="row"><div><h2>${E(x.name)} ${badge(x.ended?'Finalizada':'En curso',x.ended?'#9aaabe':'#75d8a5')}</h2><p class="muted">${date(x.started)} — ${x.ended?date(x.ended):'Actualidad'}</p></div><div class="actions">${btn('Consultar historial','sagaView',[x.id])}${permitted('sagas','manage','Editar información','sagaEdit',[x.id])}</div></div>${x.description?`<p class="block">${E(x.description)}</p>`:''}<p>${sagaRuleSummary(x.revisions.at(-1)?.rules)}</p><p class="muted">${x.revisions.length} versiones de reglas · ${reports.length} informes registrados</p></div>`}).join(''):empty('Todavía no se ha registrado ninguna saga.'))}
function sagaStart(){if(!requirePerm('sagas','manage'))return;let r=db.settings.rules;dialog('Iniciar saga',field('Nombre de la saga','name','text','',true)+field('Descripción','description','textarea','')+field('Umbral de estadísticas base','softCap','number',r.softCap,true)+field('Divisor de ganancias desde el umbral','divisor','number',r.divisor,true)+(activeSaga()?'<p class="muted">La saga actual se finalizará automáticamente al iniciar la nueva.</p>':'')+reasonField(),f=>{let name=f.name.trim(),cap=+f.softCap,div=+f.divisor,reason=auditReason(f);if(!name||!reason||!Number.isFinite(cap)||cap<0||!Number.isFinite(div)||div<1)throw Error('Introduce un nombre, motivo y parámetros válidos.');let stamp=now();return transaction([['settings'],['records','sagas']],([settings,sagas])=>{let previous=sagas.find(x=>!x.ended);if(previous){previous.ended=stamp;previous.closedBy=actor();previous.closeReason=reason}settings.rules.softCap=cap;settings.rules.divisor=div;sagas.push({id:uid(),name,description:f.description,started:stamp,ended:null,createdBy:actor(),revisions:[sagaRevision(settings.rules,reason)]})},'Inicio de saga: '+name,reason)})}
function sagaFinish(){if(!requirePerm('sagas','manage'))return;let sg=activeSaga();if(!sg)return;withReason('Finalizar '+sg.name,r=>{if(!r)throw Error('El motivo es obligatorio.');return mutate(['records','sagas'],a=>{let s=a.find(x=>x.id===sg.id);s.ended=now();s.closedBy=actor();s.closeReason=r},'Fin de saga: '+sg.name,r)})}
function sagaEdit(id){if(!requirePerm('sagas','manage'))return;let s=record('sagas',id);if(!s)return;dialog('Editar información de la saga',field('Nombre','name','text',s.name,true)+field('Descripción','description','textarea',s.description||'')+reasonField(),f=>{let name=f.name.trim(),r=auditReason(f);if(!name||!r)throw Error('Nombre y motivo obligatorios.');return mutate(['records','sagas'],a=>Object.assign(a.find(x=>x.id===id),{name,description:f.description}),'Edición de saga: '+s.name,r)})}
function sagaView(id){if(!allow('sagas'))return;let s=record('sagas',id);if(!s)return;let reports=db.records.training.filter(r=>r.sagaContext?.sagaId===id);show(s.name,`<div class="card"><p>${date(s.started)} — ${s.ended?date(s.ended):'Actualidad'}</p><p class="block">${E(s.description||'')}</p></div><h3>Historial de reglas</h3>${s.revisions.map((r,i)=>`<div class="card"><h3>Versión ${i+1}</h3><p>${date(r.at)} · ${E(r.actor.name)}</p><p>${sagaRuleSummary(r.rules)}</p><p>Motivo: ${E(r.reason||'—')}</p></div>`).join('')}<h3>Informes registrados durante la saga</h3>${allow('training')?table(['Personaje','Método','Fecha','Estado','Acciones'],reports.map(r=>[E(recordName('sheets',record('sheets',r.sheet)||{})),E(r.methodName),date(r.created),state('training',r),btn('Ver','formView',['training',r.id])])):`<p class="muted">${reports.length} informes registrados.</p>`}`)}
function goSagas(){if(!allow('sagas'))return;view='sagas';tab='';render()}


// V6: input ownership, single Ki type, granular data/action access and log filters.
function sheetMode(f){if(!f)return 'player';if(f.key==='race'||STATS.includes(f.key)||f.key==='Tipos de ki')return 'initial';if(f.inputMode)return f.inputMode;if(['Técnicas raciales','Técnicas','Transformaciones','Estilos','Controles','Estados de combate','Objetos','Cápsulas'].includes(f.key))return 'staff';return 'player'}
function modeLabel(x){return ({player:'Jugador',initial:'Solo creación',staff:'Staff'})[x]||x}
function upgrade6(d){if(d.version>=6)return;upgrade5(d);d.version=6;let fs=d.schemas.sheets.flatMap(x=>x.fields);for(let f of fs){f.inputMode=sheetMode(f);if(f.key==='Tipos de ki'){f.type='catalog';f.label='Tipo de ki';f.required=true;}if(f.key==='Armas'){f.type='textarea';f.label='Armas';f.inputMode='player';f.required=false;}}let weapons=fs.find(f=>f.key==='Armas'),ki=fs.find(f=>f.key==='Tipos de ki');for(let s of d.records.sheets){if(weapons){let old=s.values[weapons.id];if(Array.isArray(old)){let names=old.map(id=>d.records.catalogs.find(x=>x.id===id)?.name||id).join(', ');s.values[weapons.id]=[names,s.manual?.[weapons.id]].filter(Boolean).join('\n');if(s.manual)delete s.manual[weapons.id]}}if(ki&&Array.isArray(s.values[ki.id])){let old=s.values[ki.id];if(old.length===1)s.values[ki.id]=old[0];else if(old.length>1){s.previousKiTypes=old;s.values[ki.id]='';}}}for(let l of d.logs)l.kind??=logType(l);}
function kiEntries(){let c=db.categories.find(c=>c.module==='catalogs'&&c.name==='Tipos de ki');return db.records.catalogs.filter(x=>inCategory(x,c)&&!x.unavailable)}
function initialKiOptions(race,variant){if(!race)return [];return kiEntries().filter(x=>x.initial&&(!x.race||x.race===race.id)&&(!x.variant||x.variant===variant?.id)&&(!race.kiRestricted||race.kiOptions?.includes(x.id)))}
function staffKiOptions(race,r){if(!race)return [];return kiEntries().filter(x=>(!x.race||x.race===race.id)&&(!x.variant||x.variant===r.variant))}
function sheetValue(f,r){let v=r.values[f.id],old=r.manual?.[f.id];if(f.type==='race')return E(raceLabel(r));if(f.key==='Tipos de ki'&&r.previousKiTypes&&!v)return '<span class="muted">Pendiente de revisión por el Staff</span>';let displayed=displayValue(f,v);if(old){let hasValue=Array.isArray(v)?v.length:v!==undefined&&v!==null&&v!=='';return (hasValue?displayed+'<br>':'')+E(old)}return displayed}
