function controlIdentity(act,args){if(['bugSubmit','globalSearch','searchOpen'].includes(act))return null;if(['formulaEdit','formulaPreview'].includes(act))return ['settings',act];if(act==='sheetHistory')return ['sheets',act];if(act==='logView'||act==='undo')return ['logs',act];if(['dataBrowse','dataEdit','orphanDelete','usageConfig','alertDetail','alertAck'].includes(act))return ['data',act];if(act==='raceAccessEdit')return ['races',act];if(['bugDetail','bugPriority','bugDismiss','bugApprove','bugStatus','bugDelete'].includes(act))return ['bugs',act];if(['inviteEdit','inviteView','inviteToggle','inviteDelete'].includes(act))return ['settings',act];let k=view,key=act;if(['formEdit','formView','review','remove','contentEdit','contentView','recordMove','eventEdit','eventClose','ruleEdit'].includes(act)&&typeof args[0]==='string')k=args[0];if(act==='formEdit'&&!args[1])key='formCreate';if(['spinFor','spinRewardEdit','spinApprove','spinApproveUnique'].includes(act))k='spin';if(act==='spinApprove'&&args[0]&&record('spinReview',args[0])?.rarity!=='Legendario')key='spinApproveUnique';if(act==='potentialPick')k='wallet';if(act==='spinDialog')k='spin';if(act==='goSagas')return ['sagas','sagaView'];if(['ruleConfig','talentConfig','settingsSave'].includes(act))k='settings';if(['navPageEdit','navGroupEdit','navEdit','navDelete','navPageMove','navGroupMove'].includes(act))k='categories';if(['roleView','roleEdit','roleMove','roleDelete'].includes(act))k='roles';if(act==='faqEdit')return [view,'faqEdit'];if(act==='tab'||act==='password')return null;return [k,key]}
function explicitControlVisible(k,key){return !!me&&me.roles.some(id=>db.roles.find(x=>x.id===id)?.perms?.[k]?.controls?.[key]?.visible===true)}
function controlDecision(act,args,kind){if(!me)return false;if(['dataBrowse','dataEdit','orphanDelete'].includes(act)&&!isOwner())return false;if(act==='sheetHistory'&&!historyAllowed(record('sheets',args[0])))return false;if(act==='raceAccessEdit'&&!canEditRaceAccess(record('races',args[0])))return false;if(['bugApprove','bugStatus','bugDelete'].includes(act)&&!isOwner())return false;if(['bugDetail','bugPriority','bugDismiss'].includes(act)&&!bugStaff())return false;if(['inviteEdit','inviteView','inviteToggle','inviteDelete'].includes(act)&&!settingsFull())return false;if(isOwner())return true;if(['renameUser','userPassword','deleteUser','deleteLogs','selectLogs','faqEdit'].includes(act))return false;let t=controlIdentity(act,args);if(!t)return true;let [k,key]=t;let definition=controlsFor(k).find(x=>x[0]===key);if(k==='wallet'&&key==='potentialPick')return true; // choice is part of sheet creation
 if(!definition)return true;let permission=definition[2];return me.roles.some(id=>{let p=db.roles.find(x=>x.id===id)?.perms?.[k];if(!p?.view)return false;let base=!!p[permission]||(['edit','delete'].includes(permission)&&!!p.manage);let explicit=p.controls?.[key]?.[kind];return kind==='visible'?(explicit??base):base&&(explicit??true)})}
function controlAllowed(act,args){if(!modeActionAllowed(act))return false;if(!controlDecision(act,args,'execute'))return false;let t=controlIdentity(act,args);if(!t||t[1]==='potentialPick')return true;return dataAllowed(t[0],'actions')}
function applyControlVisibility(root){if(!root||!me)return;applyPageVisibility(root);root.querySelectorAll('[data-act]').forEach(b=>{let args;try{args=JSON.parse(b.dataset.args||'[]')}catch{return}let t=controlIdentity(b.dataset.act,args);if(t&&t[1]!=='potentialPick'&&b.dataset.act!=='tab'&&(!dataAllowed(t[0],'actions')||!controlDecision(b.dataset.act,args,'visible'))){b.remove();return}if(!controlAllowed(b.dataset.act,args)){b.disabled=true;b.title='Tu rol no permite ejecutar esta acción'}});cleanView(root)}
function logType(l){if(l.kind)return l.kind;let a=l.action||'';if(/reversión|deshacer/i.test(a))return 'Reversión';if(/contraseña/i.test(a))return 'Contraseñas';if(/sanci[oó]n|suspensi[oó]n|acceso de usuario/i.test(a))return 'Medidas de cuenta';if(/revisi[oó]n|aprobaci[oó]n|estado de|estado actualizado/i.test(a))return 'Revisión / estado';if(/elimin|borr|retirada/i.test(a))return 'Eliminación';if(/creaci[oó]n|crear|nuev|registro de cuenta|propuesta|informe:/i.test(a))return 'Creación / registro';if(/voto|comentario/i.test(a))return 'Participación';if(/spin|compra|saldo|inventario|recompensa/i.test(a))return 'Economía';if(/rol|permiso/i.test(a))return 'Roles / permisos';if(/saga/i.test(a))return 'Sagas';return 'Edición / configuración'}
