function bindSettingsAccess(){let f=$('#settingsform');if(!f||settingsFull())return;for(let el of f.elements){if(!el.name)continue;if(el.name==='currency'||el.name==='reason'||/^(total|period|hours)_/.test(el.name))continue;el.disabled=true}for(let el of f.querySelectorAll('button:not([data-act=settingsSave])'))el.disabled=true;for(let card of f.querySelectorAll('.card')){if(card.querySelector('input:disabled,select:disabled,textarea:disabled')){let h=card.querySelector('h2');if(h)h.insertAdjacentHTML('beforeend',' <small class="muted">· solo consulta</small>')}}}
