function old14_safeUndo(l){let paths=l.paths||[l.path],bs=l.paths?l.before:[l.before];return paths.every((p,i)=>{if(!p||!p.length||['logs','faqs'].includes(p[0])||(p[0]==='records'&&(p.length===1||p[1]==='bugs')))return false;if(p[0]==='settings'&&(p.length===1||p[1]==='invitationCodes')){let before=p.length===1?bs[i]?.invitationCodes:bs[i];let current=db.settings.invitationCodes;if(JSON.stringify(before)!==JSON.stringify(current))return false;}if(p[0]==='users')return p.length===1&&JSON.stringify(protectedUsers(bs[i]))===JSON.stringify(protectedUsers(db.users));if(p[0]==='roles')return p.length===1&&JSON.stringify(bs[i]?.find(x=>x.id==='owner'))===JSON.stringify(db.roles.find(x=>x.id==='owner'));return true})}
function backupSafeData(){let n=clone(db);n.users.forEach(u=>{delete u.hash;delete u.salt;delete u.temporary});n.faqs={};n.logs=n.logs.map(l=>faqLog(l)?{...l,before:null,after:null,reversible:false}:redact(l));return n}
function protectedRestore(n){let current=clone(db);n=clone(n);n.users=current.users;n.devices=current.devices;n.logs=current.logs;n.faqs=current.faqs;n.records.bugs=current.records.bugs;n.settings.invitationCodes=current.settings.invitationCodes;n.settings.usage=current.settings.usage;n.monitor=current.monitor;let ownerRole=current.roles.find(r=>r.id==='owner');n.roles=[ownerRole,...n.roles.filter(r=>r.id!=='owner')];for(let u of n.users)for(let id of u.roles)if(!n.roles.some(r=>r.id===id)){let role=current.roles.find(r=>r.id===id);if(role)n.roles.push(role)}n.settings.defaultRole=n.roles.some(r=>r.id===n.settings.defaultRole&&r.id!=='owner')?n.settings.defaultRole:'member';n.seq=Math.max(current.seq||0,n.seq||0);n.logs.unshift({id:uid(),at:now(),actor:actor(),action:'Restauración de copia (datos permitidos)',reason:'Restauración de Co-Owner',reversible:false,path:[],before:null,after:null});return n}
function faqDefaults(){return {
faqUser:[
['Cuenta y acceso','Regístrate con tu nombre y contraseña. Si el registro requiere invitación, pide un código al Staff. En Mi cuenta puedes cambiar tu propia contraseña. Si has perdido el acceso, abre un ticket en Discord; el Owner puede generar una contraseña temporal que deberás cambiar al entrar. No compartas tu contraseña.'],
['Crear una ficha','En Fichas, pulsa Crear ficha. Completa los apartados personales, elige una raza y variante disponibles y selecciona un tipo de ki permitido. Reparte las cuatro estadísticas sin superar el máximo inicial de la raza. El poder de pelea es la suma de fuerza, velocidad, resistencia y ki. La magia se gestiona por separado. Al guardar, elige uno de los tres talentos que salen al azar. Las tiradas no se repiten.'],
['Revisión y edición de fichas','La ficha permanece visible con su estado. El Staff revisa tus datos y puede aprobarla o rechazarla. Puedes editar tus campos personales, pero las estadísticas, técnicas, controles, transformaciones y desbloqueos quedan bajo gestión del Staff. Lee la nota de revisión si se solicitan correcciones.'],
['Razas, técnicas y requisitos','Consulta Catálogos para conocer las razas, técnicas y transformaciones. Las opciones de creación dependen de la raza, variante y disponibilidad. Las razas exclusivas de sorteo solo aparecen cuando tienes autorización. Las razas custom se proponen en Razas custom y necesitan revisión. Los requisitos condicionales ayudan a comprobar si tu personaje cumple los criterios; no sustituyen una aprobación narrativa.'],
['Entrenamientos y combates','Selecciona un personaje aprobado en Entrenamientos, el método y el lugar. Completa los datos correspondientes, compañeros, duración, turnos o resultado cuando corresponda, y aporta evidencias. Los combates se registran en esta misma sección. Respeta los requisitos y cooldowns. El Staff revisa y distribuye las ganancias; no puedes editar los puntos concedidos. El historial de sagas permite consultar los límites de cada etapa.'],
['Maestros y confianza','En Maestros consulta las enseñanzas y las relaciones de confianza. Las técnicas pueden exigir un porcentaje concreto. Participa en actividades válidas del rol y solicita su revisión al Staff. El porcentaje no se aumenta desde la ficha del jugador.'],
['Comparador y clasificación','En Comparador y Clasificación puedes comparar dos fichas, consultar diferencias y multiplicadores, y simular transformaciones desbloqueadas con sus valores configurados. La simulación no altera tus estadísticas. La clasificación ordena personajes aprobados por la estadística seleccionada.'],
['Zenis, tienda e inventario','Consulta tu saldo y objetos en Zenis e inventario. Compra artículos desde Tienda cuando tengas saldo y haya existencias. El Spin de objetos se abre desde un personaje aprobado, consume Zenis y registra el premio. Los premios que requieren revisión quedan pendientes. Puedes cambiar el estado de tus objetos si está habilitado; no puedes añadirte saldo ni premios.'],
['Sugerencias','Publica una sugerencia indicando si corresponde a Rol, Discord o Web. No puedes editarla después de publicar. Puedes votar a favor o en contra y retirar o cambiar tu voto; solo cuenta un voto por cuenta. Los comentarios publicados permanecen. Consulta el historial público de estados.'],
['Encuestas, sorteos y anuncios','En Encuestas y Sorteos puedes participar en los eventos abiertos y consultar porcentajes o resultados. Comprueba las fechas y requisitos del sorteo; algunos premios desbloquean razas exclusivas. Consulta Anuncios para las novedades oficiales.'],
['Problemas y límites','Si una opción no aparece puede estar restringida por raza, permisos, disponibilidad o estado. Si alcanzas un límite o cooldown, espera al periodo correspondiente. Informa de errores o incidencias por los canales de soporte. No intentes repetir acciones para obtener recompensas adicionales.']],
faqStaff:[
['Jerarquía y responsabilidades','Owner tiene control completo. Co-Owner gestiona todos los sistemas salvo borrar registros, gestionar contraseñas ajenas, eliminar cuentas y cambiar nombres de usuarios. Verificador revisa fichas e informes de entrenamiento; no configura sistemas ni modifica estadísticas arbitrariamente. Admin gestiona contenido y sistemas de rol, con límites específicos. Los permisos de varias funciones y los roles pueden ajustarse desde Roles y permisos. Este FAQ solo lo puede editar el Owner.'],
['Permisos y jerarquía','Acceso permite abrir un apartado. Datos visibles controla la información disponible. Los permisos generales y las acciones individuales determinan qué operaciones pueden ejecutarse. Mostrar controla la aparición de un botón. Admin puede consultar la matriz de permisos, no modificarla. Co-Owner puede crear, editar, eliminar y ordenar roles no protegidos y asignar roles a usuarios de menor jerarquía; no puede conceder Owner. El rol Owner queda protegido.'],
['Panel de cuentas','Admin solo ve nombre, rol y estado Online/Offline; no tiene botones ni detalles de actividad. Verificador no accede al panel de cuentas. Co-Owner puede consultar datos completos autorizados, sancionar, suspender, habilitar y asignar roles respetando jerarquía. Solo Owner cambia contraseñas ajenas, crea temporales, renombra y elimina cuentas. Para recuperar una cuenta, verifica su identidad por ticket antes de entregar una contraseña temporal. No hay recopilación de IP pública.'],
['Verificar fichas','Verificador, Admin, Co-Owner y Owner pueden abrir una ficha, comprobar su raza y variante, reparto inicial, datos y requisitos, y cambiar su estado indicando motivo y nota visible si procede. No se debe aprobar una ficha incorrecta. Admin y superiores pueden editar fichas ajenas y gestionar estadísticas, magia, técnicas y desbloqueos autorizados. Verificador no dispone del editor de sistemas ni del editor arbitrario de estadísticas.'],
['Revisión de entrenamientos','En Entrenamientos, abre el informe, revisa método, lugar, participantes, duración, turnos, evidencia, cooldown y contexto de saga. La ganancia sugerida es privada y orientativa. Al aprobar, distribuye los puntos autorizados entre las cuatro estadísticas conforme al reglamento. No apliques ganancias dos veces. Verificador puede revisar y conceder ganancias mediante este flujo; no altera métodos ni multiplicadores. Admin y superiores pueden configurar métodos, lugares y requisitos.'],
['Catálogos y razas','Admin, Co-Owner y Owner pueden crear, ordenar, editar y eliminar entradas oficiales; crear categorías internas desde Organización y páginas; gestionar razas, variantes, máximo inicial, bonificaciones y magia. Marca las razas exclusivas o no disponibles. Vincula técnicas raciales a su raza y variante. En Tipos de ki, el indicador Disponible desde la creación y la exclusividad racial controlan qué aparece en el selector único; los controles de ki son una categoría distinta. Verifica el efecto de cambios en fichas existentes antes de eliminar referencias.'],
['Razas custom y habilidades','Admin y superiores revisan propuestas de razas custom y sus condiciones de aprobación. Configura los puntos iniciales antes de habilitarlas. Añade técnicas exclusivas en el catálogo y asigna desbloqueos desde las fichas con un motivo. Las técnicas adquiridas y transformaciones no deben aparecer como campos editables para el jugador. Admin puede gestionar habilidades, pero no editar el saldo ni el inventario de otros jugadores.'],
['Requisitos y transformaciones','En Catálogos, edita condiciones por estadística, raza, desbloqueo, objeto, talento o confianza. Las condiciones registradas se comprueban conjuntamente. Mantén los requisitos narrativos en el texto. Para transformaciones configura los multiplicadores por estadística. El simulador usa solo formas desbloqueadas y no cambia la ficha real.'],
['Maestros','Admin y superiores pueden crear o editar maestros, información y requisitos de enseñanzas, y registrar porcentajes de confianza. Comprueba el personaje y las pruebas del roleo antes de modificar el valor. Verificador consulta la información pero no modifica la configuración.'],
['Economía y tienda','Admin y superiores pueden crear y editar productos, precios, existencias, categorías, descuentos y eventos económicos. El saldo y el inventario de otros jugadores solo los modifican Co-Owner y Owner. Cada modificación administrativa requiere justificación. No utilices un evento o artículo como atajo para conceder recompensas sin autorización.'],
['Spin y talentos','Admin y superiores configuran recompensas, coste y límites de la ruleta de objetos. La revisión de premios pendientes que modifica inventarios y la consulta de alertas quedan para Co-Owner y Owner. Los talentos se configuran en Configuración: nombres, descripciones y probabilidades que sumen 100%. Las tres tiradas iniciales se conservan y solo se elige un resultado.'],
['Sagas y reglas','Admin y superiores pueden iniciar o finalizar una saga, editar su información y configurar límites de estadísticas, divisor y otros parámetros de rol. Las revisiones se conservan en el historial. No cambies reglas pasadas ni falsees el contexto de entrenamientos antiguos. Admin no modifica la longitud de contraseña.'],
['Organización y páginas','Admin y superiores pueden crear categorías de navegación, mover apartados entre ellas, reordenarlos y crear páginas de información. El editor por bloques admite títulos, texto, listas, imágenes y enlaces. Comparador y Clasificación, y Encuestas y Sorteos, comparten navegación cuando están en la misma categoría. Los FAQ son apartados protegidos: solo Owner edita su contenido.'],
['Moldes y estados','Admin y superiores pueden agregar, mover, editar y ocultar campos de formularios, definir opciones, obligatoriedad y quién los rellena. Los cambios se aplican a fichas existentes. Co-Owner y Owner pueden configurar estados de revisión y sus efectos. Admin usa los estados existentes, no los redefine. No elimines campos que contengan datos importantes sin revisar las consecuencias.'],
['Configuración','Admin puede consultar la configuración global, pero solo modificar el nombre de la moneda, límites por usuario, reglas del rol, talentos y sagas. No puede modificar identidad visual, registro, invitaciones, mantenimiento, presencia ni política de contraseña. Co-Owner y Owner pueden gestionar esos ajustes globales.'],
['Comunidad y publicaciones','Admin puede crear, editar, cerrar encuestas y sorteos, seleccionar ganadores y publicar anuncios. Las sugerencias se consultan como cualquier usuario; no puede cambiar su estado, consultar votantes privados ni eliminarlas. Co-Owner y Owner gestionan sus estados y moderación. Los cambios de estado son públicos con fecha, autor y nota cuando exista.'],
['Registros, consumo y copias','Co-Owner y Owner consultan registros con filtros de fecha, hora, autor y tipo, antes y después y reversión cuando sea segura. Solo Owner borra registros. Co-Owner también puede consultar consumo y alertas y gestionar copias; las restauraciones del Co-Owner conservan cuentas, credenciales, nombres, registros y FAQ reservados. Admin y Verificador no acceden a registros, datos/consumo, alertas ni copias.'],
['Buenas prácticas','Escribe motivos claros en acciones administrativas. No concedas ventajas sin evidencia. Comprueba datos antes de guardar, evita aprobar dos veces y consulta requisitos y saga vigente. Si falta una regla, consulta al Owner en vez de inventarla. Si un permiso no está disponible, no intentes sortearlo. En la demo local, los permisos no equivalen todavía a seguridad de servidor.']]}}
function roleView(id){if(!allow('roles'))return;let r=db.roles.find(x=>x.id===id);if(!r)return;let yes=x=>x?'<span class="good">Sí</span>':'<span class="muted">No</span>';let reserved=['renameUser','userPassword','deleteUser','deleteLogs','selectLogs','faqEdit','dataBrowse','dataEdit','orphanDelete'];show('Permisos · '+r.name,allPermissionModules().map(([k,n])=>{let p=r.perms[k]||{},own=id==='owner';let visible=own||!!p.view;return `<details class="card"><summary>${E(n)} · ${visible?'Acceso permitido':'Sin acceso'}</summary><h3>Datos visibles</h3>${table(['Dato','Visible'],dataDefinitions(k).map(([key,label])=>[E(label),yes(own||visible&&(p.data?.[key]??defaultData(k,key,p.manage)))]))}<h3>Permisos generales</h3>${table(['Permiso','Autorizado'],(PAGE_ACTIONS[k]||ACTIONS).map(a=>[E(ACTLABEL[a]),yes(own||visible&&p[a])]))}<h3>Acciones</h3>${table(['Acción','Mostrar','Ejecutar'],controlsFor(k).map(([key,label,perm])=>{let base=visible&&(!!p[perm]||(['edit','delete'].includes(perm)&&!!p.manage)),ok=own||!reserved.includes(key);return [E(label),yes(own||ok&&visible&&(p.controls?.[key]?.visible??base)),yes(own||ok&&base&&(p.controls?.[key]?.execute??true))]}))}</details>`}).join(''))}
function upgrade7(d){if(d.version>=7)return;upgrade6(d);d.version=7;d.faqs??=faqDefaults();let help=d.menu.find(([g])=>g==='Ayuda');if(!help){help=['Ayuda',[]];d.menu.push(help)}for(let [k,n] of [['faqUser','FAQ de usuarios'],['faqStaff','FAQ de Staff']])if(!d.menu.some(([,items])=>items.some(([x])=>x===k)))help[1].push([k,n]);
let member=d.roles.find(r=>r.id==='member');if(!member){member={id:'member',name:'Miembro',color:'#9aaabe',perms:{}};d.roles.push(member)}member.perms.faqUser={view:true};member.perms.faqStaff={view:false};let publicPerms=clone(member.perms);let all=[...new Set([...d.menu.flatMap(g=>g[1].map(x=>x[0])),'spin','compare','ranking','polls','draws'])];
let p=(view=true,other={})=>({view,...other});let full=()=>p(true,Object.fromEntries(ACTIONS.map(a=>[a,true])));let verifier=clone(publicPerms);verifier.sheets={...verifier.sheets,view:true,review:true};verifier.training={...verifier.training,view:true,review:true};verifier.faqStaff=p();for(let k of ['users','roles','schemas','states','categories','settings','logs','data','backups'])verifier[k]=p(false);
let admin=clone(publicPerms);for(let k of ['sheets','races','training','catalogs','teachers','sagas','categories','schemas','settings','shop','spin','polls','draws','announcements'])admin[k]={...admin[k],...full()};admin.users={view:true,data:Object.fromEntries(userDataDefinitions().map(([k])=>[k,['name','roles','presence'].includes(k)])),controls:{}};admin.roles=p();admin.faqStaff=p();admin.settings.data={content:true,actions:true,fullSettings:false};admin.wallet={...admin.wallet,view:true,manage:false,data:{content:true,actions:true,spinAlerts:false}};admin.spin.controls={spinApprove:{visible:false,execute:false}};admin.suggestions={...publicPerms.suggestions,view:true,manage:false,review:false,delete:false};for(let k of ['states','logs','data','backups'])admin[k]=p(false);for(let k of all.filter(k=>k.startsWith('p:')))admin[k]=full();
let co={};for(let k of all)co[k]=full();co.settings.data={content:true,actions:true,fullSettings:true};co.users.data={temporary:false};co.users.controls=Object.fromEntries(['renameUser','userPassword','deleteUser'].map(k=>[k,{visible:false,execute:false}]));co.logs.controls=Object.fromEntries(['deleteLogs','selectLogs'].map(k=>[k,{visible:false,execute:false}]));co.faqStaff=p();co.faqUser=p();
let defs=[['coowner','Co-Owner','#e5b85a',co],['admin','Admin','#e28b6f',admin],['verifier','Verificador','#69b4e9',verifier]];let roles=[];for(let [id,name,color,perms] of defs){let old=d.roles.find(r=>r.id===id||r.name.toLowerCase().replace(/[ -]/g,'')===name.toLowerCase().replace(/[ -]/g,''));if(old){for(let u of d.users)u.roles=u.roles.map(x=>x===old.id?id:x);if(d.settings.defaultRole===old.id)d.settings.defaultRole=id;d.roles=d.roles.filter(r=>r!==old)}roles.push({id,name,color:old?.color||color,perms})}let owner=d.roles.find(r=>r.id==='owner');d.roles=[owner,...roles,...d.roles.filter(r=>r.id!=='owner')];
// Ordinary and malign Ki remain global; infinite remains Android-exclusive. Android energy is conditional, never auto-selected as Ki.
let cat=d.categories.find(c=>c.module==='catalogs'&&c.name==='Tipos de ki');for(let x of d.records.catalogs.filter(x=>x.category===cat?.id)){if(['Ki ordinario','Ki maligno','Ki infinito'].includes(x.name))x.initial=true;if(x.name==='Ki infinito'){x.race=d.records.raceDefinitions.find(r=>r.name==='Androides')?.id||x.race;x.autoInitial=false}}
let energy=d.records.catalogs.find(x=>x.name==='Energía ilimitada'&&x.race===d.records.raceDefinitions.find(r=>r.name==='Androides')?.id);if(energy)energy.description=(energy.description||'')+'\nSolo corresponde a androides cuyo tipo de ki es infinito.';
}

function trainingIncrements(values){let gains=STATS.map(k=>{let v=values['gain_'+k];return v==null||String(v).trim()===''?NaN:Number(v)});if(gains.some(n=>!Number.isFinite(n)||n<0))throw Error('Introduce una ganancia válida y no negativa para cada estadística.');return gains}
function trainingAwardPreview(s,gains){let before=STATS.map(k=>+val(s,k)||0),after=before.map((v,i)=>v+gains[i]);validStats(after,null);return {before,after,total:gains.reduce((a,b)=>a+b,0),beforePower:power15(before),afterPower:power15(after)}}
function reviewTraining(id){if(!requirePerm('training','review')||!controlAllowed('review',['training',id]))return;let r=record('training',id),s=record('sheets',r?.sheet);if(!s)return toast('Ficha eliminada o informe no encontrado.');let pending=!r.applied,estimate=Math.max(0,Number(r.estimate)||0),part=calc15('allocation',{total:estimate});let initial=[part,part,part,Math.max(0,Math.round((estimate-3*part)*10000)/10000)];let display=n=>Number(n.toFixed(4)).toLocaleString('es-ES',{maximumFractionDigits:4});let allocation=pending?`<div class="card" id="training-allocation" hidden><h3>Conceder estadísticas al aprobar</h3><p>Ganancia sugerida por el sistema: <b>${display(estimate)}</b> puntos (solo Staff). Ajusta y reparte la recompensa conforme al reglamento.</p><div class="datafields">${STATS.map((k,i)=>field('Añadir '+k,'gain_'+k,'number',initial[i],false)).join('')}</div><div id="training-award-preview" aria-live="polite"></div><p class="muted">La aprobación suma los puntos directamente a la ficha y registra el cambio. No necesitas acceso al editor general de estadísticas.</p></div>`:`<div class="card"><h3>Recompensa ya aplicada</h3>${Array.isArray(r.awarded)?table(['Estadística','Puntos concedidos'],STATS.map((k,i)=>[E(k),display(+r.awarded[i]||0)])):''}<p>No se pueden volver a conceder puntos desde este informe. Si hubo un error, solicita su revisión a Co-Owner.</p></div>`;
 dialog('Revisar entrenamiento',trainingDetail(r)+field('Estado','status','select',r.status,true,op(db.states.training))+field('Nota visible','note','textarea',r.reviewNote||'')+allocation+reasonField(),f=>{let live=record('training',id),sheet=record('sheets',live?.sheet);if(!live||!sheet)throw Error('El informe o personaje ya no existe.');let status=db.states.training.find(x=>x.id===f.status);if(!status)throw Error('Estado inválido.');let approval=status.effect==='approved';if(live.applied&&!approval)throw Error('La recompensa ya fue aplicada. Solicita a Co-Owner que revise o revierta el registro antes de cambiar este estado.');if(live.applied&&pending)throw Error('El informe ya se aprobó. Vuelve a abrirlo para consultar su resultado.');let apply=approval&&!live.applied,gains=apply?trainingIncrements(f):null;if(apply)trainingAwardPreview(sheet,gains);let reason=auditReason(f);if(!reason)throw Error('Introduce el motivo de la revisión.');return transaction([['records','training'],['records','sheets']],([reports,sheets])=>{let n=reports.find(x=>x.id===id),p=sheets.find(x=>x.id===sheet.id);n.status=f.status;n.reviewNote=f.note;if(apply){STATS.forEach((k,i)=>p.values[sf(k).id]=(+val(p,k)||0)+gains[i]);n.applied=true;n.awarded=gains;n.approvalSaga={...currentSagaContext(),at:now()};n.reviewedBy=actor();n.reviewedAt=now();p.trainingCount=(p.trainingCount||0)+1;if(n.outcome==='Victoria')p.wins=(p.wins||0)+1;if(n.outcome==='Derrota')p.losses=(p.losses||0)+1;}},'Revisión de informe · '+live.methodName+(apply?' · +'+display(gains.reduce((a,b)=>a+b,0))+' puntos':''),reason)},{wide:true,label:'Guardar revisión',bind:root=>{if(!pending)return;let form=root.querySelector('form'),panel=root.querySelector('#training-allocation'),preview=root.querySelector('#training-award-preview'),inputs=STATS.map(k=>form.elements.namedItem('gain_'+k));let update=()=>{let on=db.states.training.find(x=>x.id===form.elements.namedItem('status').value)?.effect==='approved';panel.hidden=!on;panel.style.display=on?'':'none';inputs.forEach(i=>{i.required=on;i.disabled=!on;i.min='0'});if(!on)return;try{let gains=trainingIncrements(formValues(form)),p=trainingAwardPreview(s,gains);preview.innerHTML=table(['Estadística','Actual','Ganancia','Resultado'],STATS.map((k,i)=>[E(k),display(p.before[i]),'+'+display(gains[i]),'<b>'+display(p.after[i])+'</b>']))+`<div class="sub"><b>Puntos concedidos: ${display(p.total)}</b><br>Poder de pelea: ${display(p.beforePower)} → ${display(p.afterPower)}</div>`}catch(e){preview.innerHTML='<p class="error">'+E(e.message)+'</p>'}};form.elements.namedItem('status').addEventListener('change',update);inputs.forEach(i=>i.addEventListener('input',update));update()}})
}

function upgrade8(d){if(d.version>=8)return;upgrade7(d);d.version=8;d.faqs??=faqDefaults();let updates={"faqStaff": {"Revisión de entrenamientos": "Verificador, Admin, Co-Owner y Owner pueden revisar informes y aplicar sus ganancias directamente, sin necesidad de que otro rango edite la ficha.\n\n1. Abre Entrenamientos y pulsa Revisar y conceder stats en el informe.\n2. Comprueba personaje, método, lugar, requisitos, participantes, duración o turnos, evidencia, cooldown y saga.\n3. Selecciona el estado de aprobación para mostrar el reparto de puntos. La ganancia sugerida es privada y orientativa: puedes ajustarla según el reglamento y la evidencia.\n4. Distribuye la recompensa entre Fuerza, Velocidad, Resistencia y Ki. Comprueba el total concedido, los valores resultantes y el poder de pelea antes de guardar.\n5. Escribe el motivo y, si corresponde, una nota visible. Al guardar, la web añade los puntos a la ficha y marca el informe como aplicado. No hace falta notificar a Admin por una aprobación ordinaria.\n\nSi el informe no cumple las condiciones, selecciona un estado de revisión o rechazo; no se sumarán puntos. Si detectas un error en una recompensa ya aplicada, notifícalo a Co-Owner para revisar el registro y, cuando proceda, revertirlo. Verificador no puede editar libremente estadísticas ni configurar los métodos de entrenamiento.", "Spin y talentos": "El Spin de inventario es automático una vez que el jugador realiza la tirada: consume Zenis, registra el resultado y concede el objeto sin intervención del Staff. Los premios comunes, poco comunes, raros y épicos se incorporan automáticamente. Excepciones: los legendarios y los objetos únicos repetidos quedan pendientes de revisión, según el reglamento. Co-Owner y Owner revisan esas recompensas y las alertas de tiradas; Admin configura premios, precio y límites, pero no modifica inventarios ajenos. No etiquetes a nadie por un Spin ordinario.\n\nLos talentos se configuran en Configuración: nombres, descripciones y probabilidades que sumen 100%. Las tres tiradas iniciales se conservan y solo se elige un resultado.", "Buenas prácticas": "Escribe motivos claros en acciones administrativas. No concedas ventajas sin evidencia. Comprueba datos antes de guardar, evita aprobar dos veces y consulta requisitos y saga vigente. Si falta una regla o configuración que Admin pueda resolver, consulta primero a Admin. Si se trata de una decisión reservada al Owner, reúne antes toda la información y sigue la guía de tags. No intentes eludir los permisos. En la demo local, los permisos no equivalen a seguridad de servidor.", "Guía de tags y escalado en Discord": "Principio general: el Staff que reclama un asunto se encarga de resolver todo lo que esté dentro de sus permisos. No se etiqueta a un rango superior por comodidad, para pedir confirmación innecesaria o cuando un rango inferior puede resolver el asunto. Evita menciones masivas y no etiquetes a varios rangos simultáneamente.\n\nVERIFICADOR: resuelve directamente revisiones de fichas y entrenamientos, incluidos los puntos del entrenamiento. Si necesitas editar una ficha fuera de ese flujo, configurar razas, catálogos, maestros, métodos de entrenamiento, talentos, páginas o economía, avisa a un Admin. No etiquetes a Co-Owner ni Owner para tareas que Admin pueda realizar.\n\nADMIN: resuelve las tareas de gestión de rol, contenido, catálogos, fichas, entrenamientos, maestros, economía y eventos autorizadas. Si el asunto requiere sancionar una cuenta, cambiar roles o permisos, modificar saldo o inventario ajeno, gestionar sugerencias, revertir registros, revisar premios pendientes o acceder a configuraciones protegidas, avisa a Co-Owner. No etiquetes a Owner para esas tareas.\n\nCO-OWNER: resuelve cualquier asunto que esté dentro de sus permisos. Solo deriva a Owner las acciones reservadas a él: restablecer contraseñas ajenas, renombrar o eliminar cuentas, eliminar registros, editar el FAQ protegido, o decisiones que el Owner se haya reservado expresamente.\n\nRECUPERACIÓN DE CUENTAS: ningún rango debe etiquetar al Owner al abrir el ticket. Sigue primero el protocolo de recuperación y recopila todas las respuestas. Solo entonces menciona al Owner una única vez.\n\nAl escalar cualquier otra incidencia, indica el problema, los datos relevantes, lo que ya has comprobado y qué acción concreta requiere el rango superior. Si el rango adecuado aún no responde, deja el asunto documentado; no encadenes tags ni saltes jerarquías por impaciencia.", "Protocolo de ticket: recuperación de contraseña": "1. Un miembro del Staff reclama el ticket y asume su gestión inicial. No etiquetes al Owner todavía.\n\n2. Pregunta al usuario, sin mostrarle los datos guardados en la web ni sugerirle respuestas:\n• ¿Cuál es tu usuario en la web?\n• ¿En qué navegador/es has entrado a la web?\n• ¿Desde qué dispositivo/s accediste normalmente (ordenador, móvil o tableta) y qué sistema operativo utilizabas en cada uno?\n• ¿Cuándo accediste por última vez a la cuenta? Indica una fecha y hora aproximadas.\n• ¿Desde qué zona horaria accedías habitualmente?\n• ¿Cuándo creaste aproximadamente la cuenta?\n• ¿Qué personajes tienes o tenías en la web? Indica sus nombres y razas, si tenías alguno. Si no tienes personajes, indícalo.\n\n3. Espera a que el usuario responda TODAS las preguntas. Si falta alguna respuesta, pide que la complete. No anticipes ni confirmes datos de la cuenta; no solicites contraseñas actuales o antiguas, códigos de acceso, IP, documentos de identidad ni datos innecesarios. Si no recuerda algún dato, recoge esa circunstancia y solicita que aporte información alternativa útil antes de elevarlo.\n\n4. Cuando TODAS las respuestas estén en el ticket y se haya reunido la información solicitada, etiqueta al Owner UNA SOLA VEZ en ese mismo ticket. Resume el usuario y deja las respuestas originales disponibles. El Owner se encarga del resto: contrastar la información, decidir si acredita suficientemente la titularidad y, si procede, generar y entregar una contraseña temporal. No etiquetes a Admin o Co-Owner para que restablezcan la contraseña, porque carecen de ese permiso.\n\n5. No prometas la recuperación ni confirmes la identidad por tu cuenta. Las respuestas sirven como indicios, no como prueba definitiva. El Owner decidirá si requiere datos adicionales. El usuario deberá cambiar la contraseña temporal al entrar. Mantén el ticket y sus respuestas privados."}, "faqUser": {"Zenis, tienda e inventario": "Consulta tu saldo y objetos en Zenis e inventario. Compra artículos desde Tienda cuando tengas saldo y haya existencias. El Spin de objetos se abre desde un personaje aprobado, consume Zenis y concede automáticamente las recompensas. Los objetos legendarios y los objetos únicos repetidos requieren revisión antes de poder usarlos. No necesitas contactar con el Staff para las demás tiradas. No puedes añadirte saldo ni premios."}};for(let [section,changes] of Object.entries(updates)){d.faqs[section]??=[];for(let [question,answer] of Object.entries(changes)){let i=d.faqs[section].findIndex(q=>q[0]===question);if(i>=0)d.faqs[section][i]=[question,answer];else d.faqs[section].push([question,answer]);}}}
function upgrade9(d){if(d.version>=9)return;upgrade8(d);d.version=9;
for(const role of d.roles){const p=role.perms?.spin;if(!p)continue;p.controls??={};const previous=p.controls.spinApprove||{visible:!!p.manage,execute:!!p.manage};p.controls.spinApproveUnique??={...previous};if(role.id==='admin'){p.view=true;p.manage=true;p.controls.spinApprove={visible:true,execute:true};p.controls.spinApproveUnique={visible:false,execute:false};}}
for(const q of d.faqs?.faqStaff||[]){q[1]=q[1].replace('Co-Owner y Owner revisan esas recompensas y las alertas de tiradas; Admin configura premios, precio y límites, pero no modifica inventarios ajenos.','Admin, Co-Owner y Owner revisan premios legendarios. Los objetos únicos repetidos no legendarios y las alertas de tiradas corresponden a Co-Owner y Owner. Admin configura premios, precio y límites, pero no puede editar libremente inventarios ajenos.').replace('revertir registros, revisar premios pendientes o acceder','revertir registros, revisar objetos únicos repetidos no legendarios o acceder').replace('Admin configura premios, precio y límites, pero no modifica inventarios ajenos.','Admin configura premios, precio y límites, y revisa premios legendarios, pero no modifica libremente inventarios ajenos.');if(q[0]==='Guía de tags y escalado en Discord'&&!q[1].includes('No etiquetes a Co-Owner por un premio legendario'))q[1]+='\n\nSPIN LEGENDARIO: Verificador avisa a Admin cuando un premio legendario requiere revisión. Admin puede aprobarlo o rechazarlo directamente. No etiquetes a Co-Owner por un premio legendario ordinario ni a Owner. Los objetos únicos repetidos no legendarios siguen el escalado a Co-Owner.';}}
const FAQ10_DEFAULTS={"faqUser":[["¿Cómo creo mi cuenta?","Abre el registro, introduce un nombre de usuario y una contraseña que cumpla los requisitos indicados. Si se solicita un código de invitación, pídelo por el canal de soporte. Utiliza una contraseña distinta de la de Discord.",{"group":"Cuenta","roles":[],"requires":[]}],["¿Cómo cambio mi contraseña?","Abre Mi cuenta y pulsa Cambiar contraseña. Introduce la contraseña actual, la nueva y su confirmación. No compartas ninguna contraseña con otros usuarios.",{"group":"Cuenta","roles":[],"requires":[]}],["He perdido mi contraseña. ¿Qué hago?","Abre un ticket de recuperación en Discord. El Staff te pedirá información sobre tu cuenta para comprobar la titularidad. Contesta todas las preguntas en el ticket privado. Si se autoriza la recuperación, recibirás instrucciones para entrar y cambiar tu contraseña. Nunca envíes tu contraseña anterior.",{"group":"Cuenta","roles":[],"requires":[]}],["¿Por qué no puedo acceder o registrarme?","Lee el mensaje que aparece en pantalla. El registro puede estar cerrado, requerir invitación o existir una interrupción temporal. Si el problema persiste, abre un ticket e indica el mensaje exacto, sin compartir contraseñas.",{"group":"Cuenta","roles":[],"requires":[]}],["¿Cómo consulto una ficha?","Abre Fichas y busca el personaje por su nombre. Pulsa Ver para abrir los apartados que tu cuenta puede consultar. El estado indica la situación de su revisión. Una ficha pendiente no equivale a una aprobación.",{"group":"Personajes","roles":[],"requires":["sheets","sheets:action:formView","sheets:data:status"]}],["¿Cómo creo un personaje?","En Fichas pulsa Crear. Rellena los campos obligatorios y elige las opciones disponibles en los selectores. El formulario solo muestra los campos que te corresponde rellenar. Guarda la ficha para enviarla a revisión.",{"group":"Personajes","roles":[],"requires":["sheets:action:formCreate"]}],["¿Cómo elijo raza, variante y tipo de ki?","En la creación elige primero la raza y su variante, si la tiene. El selector de tipo de ki se ajusta a esa elección y permite seleccionar uno. Los controles de ki y los tipos de ki son conceptos distintos. Las opciones que no aparecen no están disponibles para tu personaje en ese momento.",{"group":"Personajes","roles":[],"requires":["sheets:action:formCreate"]}],["¿Cómo reparto las estadísticas iniciales?","Distribuye los puntos disponibles entre Fuerza, Velocidad, Resistencia y Ki. No introduzcas valores negativos ni superes el máximo de tu raza y variante. El poder de pelea se obtiene sumando las cuatro estadísticas. La magia se mide aparte. No hace falta calcular el total a mano.",{"group":"Personajes","roles":[],"requires":["sheets:action:formCreate","sheets:data:stats"]}],["¿Cómo se obtiene el talento?","Al terminar de crear la ficha, elige uno de los tres resultados aleatorios ofrecidos. La elección queda guardada; no puedes repetir las tiradas para buscar otro resultado. Si todavía no lo has elegido, consulta tu personaje en Zenis e inventario.",{"group":"Personajes","roles":[],"requires":["sheets:action:formCreate","wallet","wallet:data:content"]}],["¿Cómo edito mi ficha?","Abre tu propia ficha y pulsa Editar cuando esté disponible. Modifica los datos personales que aparecen en el formulario. Los campos que no aparecen no son editables por el jugador. Si necesitas corregir un dato que no puedes cambiar, contacta con el Staff indicando el personaje y el cambio solicitado.",{"group":"Personajes","roles":[],"requires":["sheets:action:formEdit"]}],["¿Cómo consigo técnicas y transformaciones?","Las habilidades se obtienen mediante las reglas del rol. Consulta sus requisitos y aporta al Staff la evidencia del aprendizaje o desbloqueo. El personaje debe cumplir las condiciones aplicables; no basta con añadir un nombre en la ficha.",{"group":"Personajes","roles":[],"requires":["catalogs:data:content","sheets:data:progress"]}],["¿Cómo funciona el comparador?","Selecciona dos personajes y pulsa Comparar. Consulta los valores, diferencias y multiplicadores de cada estadística y del poder total. Una ventaja de poder no decide por sí sola el combate narrativo.",{"group":"Personajes","roles":[],"requires":["compare:action:compare","sheets:data:stats"]}],["¿Qué hace el simulador de transformaciones?","En Comparador selecciona las formas desbloqueadas que quieras simular. El resultado aplica los multiplicadores configurados sin alterar las estadísticas reales de ninguna ficha.",{"group":"Personajes","roles":[],"requires":["compare:action:simulatorSelect","sheets:data:stats"]}],["¿Cómo funciona la clasificación?","Abre Clasificación desde la pestaña correspondiente y elige la estadística por la que deseas ordenar los personajes aprobados. El ranking no modifica fichas ni concede premios.",{"group":"Personajes","roles":[],"requires":["ranking:data:content","sheets:data:stats"]}],["¿Dónde consulto razas, técnicas y objetos?","En Catálogos, despliega las categorías y abre una entrada para consultar la información que esté disponible. Las categorías permiten organizar diferentes clases de contenido.",{"group":"Razas y aprendizaje","roles":[],"requires":["catalogs:action:contentView"]}],["¿Cómo propongo una raza custom?","En Razas custom pulsa Crear. Completa el nombre, planeta de origen, descripción, características, habilidades, ventajas, desventajas, lore y demás campos solicitados. La propuesta se somete a revisión; no podrás usarla como raza disponible hasta que se apruebe y habilite.",{"group":"Razas y aprendizaje","roles":[],"requires":["races:action:formCreate"]}],["¿Qué significa un requisito condicional?","Si una entrada permite consultar requisitos, selecciona el personaje y comprueba las condiciones. Los requisitos numéricos o de desbloqueo pueden comprobarse automáticamente; las condiciones narrativas deben demostrarse mediante el rol.",{"group":"Razas y aprendizaje","roles":[],"requires":["catalogs:action:checkConditions"]}],["¿Cómo registro un entrenamiento?","En Entrenamientos pulsa Registrar entrenamiento. Selecciona un personaje aprobado, el método y el lugar. Rellena duración, compañeros, evidencia y los demás datos que correspondan. Lee los requisitos antes de enviar.",{"group":"Entrenamientos","roles":[],"requires":["training:action:formCreate"]}],["¿Cómo registro un combate?","Los combates son métodos de entrenamiento. Selecciona el método de combate correspondiente e indica los turnos, resultado y evidencias que solicite el formulario. No dupliques un mismo enfrentamiento para obtener puntos varias veces.",{"group":"Entrenamientos","roles":[],"requires":["training:action:formCreate"]}],["¿Cuándo aumentan mis estadísticas?","El Staff revisa tu informe y, cuando lo aprueba, aplica la recompensa a tu personaje. Consulta el estado del informe y el poder actualizado de tu ficha. Un informe enviado no concede puntos inmediatamente.",{"group":"Entrenamientos","roles":[],"requires":["training:data:status","sheets:data:stats"]}],["¿Qué son los cooldowns y requisitos?","Cada método tiene condiciones y un intervalo antes de poder repetirlo. Comprueba la duración, turnos, compañeros y restricciones del lugar. Si la web rechaza el envío, lee el motivo y corrige los datos o espera el tiempo necesario.",{"group":"Entrenamientos","roles":[],"requires":["training:action:formCreate"]}],["¿Para qué sirve el historial de sagas?","Consulta la etapa actual del rol y sus reglas de ganancia. Las sagas anteriores conservan su contexto para entender las recompensas y límites aplicables en cada momento.",{"group":"Entrenamientos","roles":[],"requires":["sagas:action:sagaView"]}],["¿Cómo se obtiene confianza con maestros?","Consulta la información del maestro y sus enseñanzas. Realiza las actividades del rol que correspondan y aporta la evidencia al Staff. La confianza es individual para cada personaje y puede ser requisito para determinadas técnicas.",{"group":"Razas y aprendizaje","roles":[],"requires":["teachers:data:content"]}],["¿Cómo consulto mis Zenis y objetos?","Abre Zenis e inventario. Consulta el saldo de la cuenta y los objetos de tus personajes. Si un objeto permite cambiar su estado, usa la opción correspondiente sin alterar su identidad ni cantidad.",{"group":"Economía","roles":[],"requires":["wallet:data:content"]}],["¿Cómo compro un objeto?","En Tienda revisa el producto, precio vigente y existencias. Pulsa Comprar, selecciona un personaje propio aprobado y la cantidad. Comprueba el saldo antes de confirmar; los objetos comprados se añaden al inventario del personaje seleccionado.",{"group":"Economía","roles":[],"requires":["shop:action:buy"]}],["¿Cómo funciona el Spin?","En Zenis e inventario abre el Spin de uno de tus personajes aprobados. Comprueba el precio, saldo y disponibilidad; después pulsa Girar ruleta. El importe se descuenta y los premios ordinarios se incorporan automáticamente. Los legendarios y los objetos únicos repetidos esperan revisión. No hace falta abrir un ticket por cada tirada.",{"group":"Economía","roles":[],"requires":["wallet:data:content","spin:action:spinFor"]}],["¿Cómo publico una sugerencia?","En Sugerencias pulsa Nueva sugerencia, indica Rol, Discord o Web y explica la propuesta. Revisa el texto antes de enviarlo: una sugerencia publicada no se puede editar.",{"group":"Comunidad","roles":[],"requires":["suggestions:action:suggestEdit"]}],["¿Cómo voto una sugerencia?","Puedes votar a favor o en contra y retirar o cambiar tu voto. Solo cuenta un voto por cuenta.",{"group":"Comunidad","roles":[],"requires":["suggestions:action:vote","suggestions:data:votes"]}],["¿Cómo comento una sugerencia?","Pulsa Comentar, escribe una aportación relacionada y revisa el texto. Los comentarios publicados permanecen. Mantén el respeto y evita repetir mensajes.",{"group":"Comunidad","roles":[],"requires":["suggestions:action:comment","suggestions:data:comments"]}],["¿Cómo consulto el estado de una sugerencia?","En la sugerencia consulta el estado y el historial público de cambios. Cuando haya una modificación podrás ver su fecha, autor y comentario si se incluyó.",{"group":"Comunidad","roles":[],"requires":["suggestions:data:history"]}],["¿Cómo participo en una encuesta?","Abre Encuestas, elige una opción y vota mientras siga abierta. Puedes retirar el voto pulsando la opción que has votado.",{"group":"Comunidad","roles":[],"requires":["polls:action:pollVote"]}],["¿Cómo se interpretan los porcentajes de una encuesta?","Cada porcentaje representa los votos de esa opción respecto al total de votos registrados. Si no hay votos, se muestra cero.",{"group":"Comunidad","roles":[],"requires":["polls:data:results"]}],["¿Cómo participo en un sorteo?","Abre Sorteos, lee los requisitos y participa mientras esté abierto. Puedes retirar tu participación antes del cierre. Comprueba los resultados publicados cuando termine.",{"group":"Comunidad","roles":[],"requires":["draws:action:drawJoin","draws:data:results"]}],["¿Dónde se publican las novedades?","En Anuncios consulta las publicaciones oficiales y sus fechas. Lee los enlaces, imágenes o instrucciones incluidos antes de participar en una actividad.",{"group":"Comunidad","roles":[],"requires":["announcements:data:content"]}],["¿Qué hago si encuentro un fallo?","Abre un ticket con el apartado, lo que intentabas hacer, el mensaje que apareció y, si es posible, una captura sin datos privados. Evita repetir una operación de compra, recompensa o registro si no sabes si se guardó.",{"group":"Soporte","roles":[],"requires":[]}]],"faqStaff":[["Cómo trabajar como Verificador","Tu tarea es revisar con rigor las fichas e informes que tengas asignados. Resuelve las revisiones ordinarias tú mismo. Si hay un dato incompleto, explica qué debe corregirse; si el caso requiere una intervención fuera de tus permisos, reúne la información y avisa a Admin.",{"group":"Responsabilidades","roles":["verifier"],"requires":[]}],["Cómo trabajar como Admin","Gestiona las funciones de rol y contenido que aparecen en tu manual. Antes de cambiar una regla, comprueba el reglamento y cómo afectará a los personajes. Resuelve las tareas autorizadas sin trasladarlas a un rango superior.",{"group":"Responsabilidades","roles":["admin"],"requires":[]}],["Cómo trabajar como Co-Owner","Coordina al equipo, resuelve incidencias escaladas y supervisa las operaciones que tu cuenta permite. Delega las tareas ordinarias al rango competente. No uses una función general para eludir una restricción de tu rango.",{"group":"Responsabilidades","roles":["coowner"],"requires":[]}],["Cómo trabajar como Owner","Supervisa la plataforma, define los permisos y decide las excepciones de gestión. Comprueba el efecto de los cambios sobre las cuentas y los sistemas antes de guardarlos. Este manual puede editarse desde el botón Editar preguntas.",{"group":"Responsabilidades","roles":["owner"],"requires":[]}],["Motivos y comprobaciones","En las operaciones administrativas que soliciten motivo, escribe una explicación concreta: qué cambia, por qué y qué evidencia lo justifica. No apruebes por conveniencia, no inventes reglas y comprueba el resultado antes de repetir una operación.",{"group":"Responsabilidades","roles":[],"requires":[]}],["Guía de tags: Verificador","Resuelve tus revisiones sin etiquetar a nadie. Si la petición supera tus permisos, avisa a un Admin y explica el caso, lo comprobado y la intervención necesaria. No etiquetes a Co-Owner ni a Owner por tareas que Admin pueda resolver. La recuperación de contraseñas sigue su protocolo especial. Si una ficha necesita una corrección que no puedes realizar desde tu revisión, traslada el caso a Admin. Si un usuario consulta una recompensa legendaria pendiente, puedes derivar esa consulta a Admin; no hace falta etiquetar al Owner.",{"group":"Responsabilidades","roles":["verifier"],"requires":[]}],["Guía de tags: Admin","Resuelve las tareas que figuran en tu manual. Si una intervención queda fuera de tus permisos, avisa a Co-Owner con el contexto y la acción necesaria. No etiquetes a Owner por trabajo que pueda resolver Co-Owner o el propio equipo. Si es una recuperación de contraseña, aplica su protocolo especial; si se trata de otra petición expresamente reservada al Owner, eleva el caso por la vía adecuada con la información completa. No solicites intervención superior para aprobar fichas, revisar entrenamientos, gestionar contenido o resolver premios legendarios si ya dispones de los controles correspondientes.",{"group":"Responsabilidades","roles":["admin"],"requires":[]}],["Guía de tags: Co-Owner","Resuelve las incidencias que puedas gestionar. Si una tarea puede realizarla un Admin o Verificador, coordina con ese rango sin etiquetar al Owner. Para una intervención expresamente reservada al Owner, reúne las pruebas y solicita únicamente esa intervención. La recuperación de contraseña requiere completar su protocolo antes del tag. No intervengas en cada revisión ordinaria: deja que la gestione el Staff autorizado y actúa únicamente si necesita ayuda o si existe una incidencia justificada.",{"group":"Responsabilidades","roles":["coowner"],"requires":[]}],["Guía de tags: otros roles de Staff","Resuelve las tareas permitidas por tu cuenta. Si no puedes resolver una intervención, contacta con el rango competente más cercano sin saltar la jerarquía. Para recuperación de contraseñas sigue el procedimiento específico.",{"group":"Responsabilidades","roles":["@custom"],"requires":[]}],["Cómo entregar una incidencia al rango competente","Reclama el ticket si corresponde. Antes de escalar, recopila usuario, personaje o registro afectado, fecha aproximada, problema, pruebas y comprobaciones ya realizadas. Indica qué actuación falta. Etiqueta una sola vez al rango competente; no hagas menciones masivas ni encadenes tags.",{"group":"Responsabilidades","roles":[],"requires":[]}],["Ticket de recuperación de contraseña","1. Reclama el ticket. No etiquetes al Owner todavía.\n\n2. Pregunta al usuario, sin dar pistas ni mostrar datos de la web:\n• ¿Cuál es tu usuario en la web?\n• ¿En qué navegador/es has entrado a la web?\n• ¿Desde qué dispositivos y sistemas operativos has accedido?\n• ¿Cuándo accediste por última vez? Indica fecha y hora aproximadas.\n• ¿Desde qué zona horaria accedías habitualmente?\n• ¿Cuándo creaste aproximadamente la cuenta?\n• ¿Qué personajes tienes o tenías y cuáles son sus razas? Si no tienes ninguno, indícalo.\n\n3. Espera a que responda TODAS las preguntas. Si no recuerda un dato, documenta la circunstancia y solicita información alternativa útil. No pidas contraseñas, IP, documentos de identidad ni códigos. No confirmes si las respuestas coinciden.\n\n4. ÚNICAMENTE cuando el ticket contenga todas las respuestas y la información solicitada, etiqueta al Owner UNA SOLA VEZ en ese ticket. El Owner asume el resto. No etiquetes a Admin ni a Co-Owner para que realicen la recuperación.\n\n5. No prometas la recuperación. Mantén la conversación privada; la titularidad la decide el Owner.",{"group":"Soporte","roles":[],"requires":[]}],["Revisar fichas paso a paso","1. Abre Fichas y localiza el personaje.\n2. Comprueba los datos obligatorios, raza y variante, tipo de ki, requisitos y reparto inicial de las cuatro estadísticas.\n3. Comprueba la coherencia del lore con el reglamento.\n4. Pulsa Revisar, selecciona el estado adecuado, añade una nota visible si necesita correcciones y escribe el motivo.\n5. Comprueba el estado guardado. Si la ficha no es válida, no la apruebes hasta que se corrija.",{"group":"Personajes","roles":[],"requires":["sheets:action:review","sheets:data:stats","sheets:data:status","sheets:action:formView"]}],["Editar fichas ajenas","Desde Fichas abre el personaje y utiliza Editar. Corrige únicamente los campos afectados, conserva los demás datos y justifica la modificación. Para cambiar estadísticas o desbloqueos utiliza sus procedimientos específicos, en vez de modificar datos personales como atajo.",{"group":"Personajes","roles":[],"requires":["sheets:action:formEdit","sheets:perm:manage"]}],["Edición directa de estadísticas","Utiliza la opción de editar estadísticas de la ficha. Comprueba el poder anterior, introduce los valores absolutos autorizados y revisa el total. La magia se gestiona separadamente. Escribe el motivo y guarda. No sustituyas una aprobación ordinaria de entrenamiento por una edición manual; perderías la relación con el informe.",{"group":"Personajes","roles":[],"requires":["sheets:action:statEdit","sheets:data:stats"]}],["Gestionar habilidades, controles y transformaciones","En la ficha abre Habilidades y desbloqueos. Selecciona las entradas compatibles con la raza y variante, revisa sus requisitos y conserva las ya adquiridas que deban mantenerse. Comprueba el tipo de ki y distingue este de los controles. Introduce el motivo y guarda. Si falta una entrada, no inventes un desbloqueo.",{"group":"Personajes","roles":[],"requires":["sheets:action:grantSheet"]}],["Revisar y conceder estadísticas","1. Abre Entrenamientos y pulsa Revisar y conceder stats.\n2. Comprueba personaje, método, lugar, requisitos, participantes, duración o turnos, resultado, evidencia y cooldown.\n3. Consulta la ganancia sugerida como referencia privada; no es una recompensa prometida.\n4. Si apruebas, reparte los puntos autorizados entre Fuerza, Velocidad, Resistencia y Ki. Comprueba el total y el poder resultante en la vista previa.\n5. Escribe el motivo y, si procede, una nota visible. Guarda. Las estadísticas se suman y el informe queda aplicado. No necesitas etiquetar a otro rango para conceder estos puntos.\nSi no cumple el reglamento, elige un estado que no apruebe y explica la corrección. No concedas puntos dos veces.",{"group":"Entrenamientos","roles":[],"requires":["training:action:review","training:data:details"]}],["Incidencias con entrenamientos ya aprobados","Si encuentras un error en una recompensa aplicada, identifica el informe, personaje, puntos concedidos y motivo de la corrección. No envíes otro informe ni vuelvas a aprobar el mismo para compensarlo. Escala la incidencia por la guía de tags cuando no puedas resolverla.",{"group":"Entrenamientos","roles":[],"requires":["training:action:review","training:data:details"]}],["Crear o editar métodos de entrenamiento","En Entrenamientos abre la configuración de métodos. Añade o edita el nombre y el tipo: entrenamiento, narrativo o combate. Define multiplicador, ganancia por hora o victoria, derrota, duración máxima, turnos mínimos, cooldown, requisito de maestro y texto de requisitos según el reglamento. Guarda con motivo y comprueba el formulario de registro.",{"group":"Entrenamientos","roles":[],"requires":["training:action:trainingConfig"]}],["Configurar lugares de entrenamiento","En la configuración de Entrenamientos añade o edita un lugar. Indica nombre, multiplicador de entrenamiento, multiplicador de combate, requisitos e incompatibilidad con maestro si procede. El jugador verá los requisitos al elegirlo. Comprueba la compatibilidad con los métodos previstos.",{"group":"Entrenamientos","roles":[],"requires":["training:action:trainingConfig"]}],["Eliminar métodos o lugares","Localiza la entrada en la configuración y pulsa Eliminar. Revisa antes los informes que dependan de ella y explica por qué deja de estar disponible. No borres un método solo para cambiar su multiplicador; edítalo.",{"group":"Entrenamientos","roles":[],"requires":["training:action:configDelete"]}],["Crear y editar entradas de catálogo","Abre Catálogos y añade una entrada dentro de la categoría adecuada. Rellena nombre, descripción, imagen, requisitos y bloques de información. Si es exclusiva, selecciona raza y variante compatibles. Disponible desde la creación habilita la selección inicial; Asignar automáticamente concede la entrada al crear si corresponde. No disponible la retira de la selección. Guarda y comprueba el resultado.",{"group":"Catálogos y razas","roles":[],"requires":["catalogs:action:contentEdit"]}],["Configurar una raza y sus variantes","En Catálogos abre la gestión de razas. Indica nombre, descripción, imagen, magia inicial y máxima, y variantes. Cada línea de variante sigue el formato nombre | máximo inicial | bonus sumable | magia extra. Los valores no deben ser negativos; deja sin habilitar las razas cuyos límites estén pendientes. Marca exclusiva o no disponible cuando corresponda.",{"group":"Catálogos y razas","roles":[],"requires":["catalogs:action:raceConfig"]}],["Configurar tipos de ki y técnicas raciales","En la configuración de raza puedes limitar sus tipos de ki iniciales a entradas compatibles. En Catálogos, utiliza la categoría Tipos de ki y la disponibilidad inicial para definir el selector único. En técnicas raciales, vincula la raza y, si procede, la variante. Usa la asignación automática solo para habilidades iniciales reales. No clasifiques los controles de ki como tipos de energía.",{"group":"Catálogos y razas","roles":[],"requires":["catalogs:action:raceConfig","catalogs:action:contentEdit"]}],["Revisar razas custom","Abre la propuesta en Razas custom y revisa características, ventajas, desventajas, habilidades, transformaciones y lore. Solicita correcciones mediante la nota de revisión si procede. Utiliza el estado correspondiente y deja un motivo.",{"group":"Catálogos y razas","roles":[],"requires":["races:action:review"]}],["Habilitar una raza custom aprobada","Comprueba que la propuesta haya sido aprobada. Configura sus variantes, puntos iniciales, magia y disponibilidad en Catálogos antes de permitir su uso; añade las técnicas raciales y sus condiciones correspondientes. Comprueba que aparezca únicamente para quienes puedan seleccionarla.",{"group":"Catálogos y razas","roles":[],"requires":["races:action:review","catalogs:action:raceConfig","catalogs:action:contentEdit"]}],["Editar requisitos condicionales","Desde la entrada de catálogo abre Requisitos. Añade las condiciones necesarias por estadística, raza, desbloqueo, objeto, talento o confianza. Las condiciones se verifican conjuntamente. Comprueba el tipo y valor de cada condición; conserva en la descripción los requisitos narrativos que la web no puede verificar.",{"group":"Catálogos y razas","roles":[],"requires":["catalogs:action:conditionsEdit"]}],["Configurar multiplicadores de transformaciones","En la entrada de transformación abre Multiplicadores. Introduce el factor correspondiente a cada estadística según el reglamento. Revisa los valores con el simulador antes de utilizarlos como referencia. No modifiques las estadísticas base de los personajes para representar una transformación temporal.",{"group":"Catálogos y razas","roles":[],"requires":["catalogs:action:transformEdit","compare:action:simulatorSelect"]}],["Ordenar o eliminar contenido oficial","Usa los controles de reordenación para cambiar la posición de las entradas. Antes de eliminar una técnica, objeto o raza, comprueba si existen personajes u otras entradas que dependan de ella. Si solo está temporalmente deshabilitada, utiliza su disponibilidad.",{"group":"Catálogos y razas","roles":[],"requires":["catalogs:action:recordMove","catalogs:action:remove"]}],["Crear o editar un maestro","Abre Maestros y pulsa Añadir maestro o Editar. Rellena su nombre, descripción y confianza inicial según el reglamento. Mantén actualizadas las enseñanzas y sus condiciones en las entradas correspondientes del catálogo.",{"group":"Maestros","roles":[],"requires":["teachers:action:ruleEdit","catalogs:data:content"]}],["Modificar confianza","En Maestros pulsa Modificar confianza, elige el personaje y establece el porcentaje total entre 0 y 100. Comprueba el valor anterior y la evidencia de la actividad. Introduce el motivo. No confundas el incremento concedido con el porcentaje total resultante.",{"group":"Maestros","roles":[],"requires":["teachers:action:trust"]}],["Crear y editar productos","En Tienda añade o edita un producto: selecciona su categoría, nombre, información, imagen, precio y existencias según el formulario. Comprueba que los datos sean correctos antes de publicar. Usa la edición para actualizar un producto existente en vez de duplicarlo.",{"group":"Economía","roles":[],"requires":["shop:action:contentEdit"]}],["Rebajas y eventos económicos","En Tienda utiliza Rebaja para aplicar descuentos a un producto. En Eventos económicos configura activación, intervalo y variación mínima y máxima; Aplicar evento permite ejecutar uno autorizado. Comprueba precios y condiciones antes de guardar.",{"group":"Economía","roles":[],"requires":["shop:action:discountEdit","shop:action:marketConfig","shop:action:marketEvent"]}],["Ordenar y retirar productos","Utiliza los controles de orden de la tienda y elimina únicamente productos que realmente deban retirarse. Comprueba que no estás afectando a una compra o evento en curso.",{"group":"Economía","roles":[],"requires":["shop:action:recordMove","shop:action:remove"]}],["Configurar las recompensas del Spin","En Zenis e inventario busca Configuración de recompensas Spin. Pulsa Añadir premio, selecciona un objeto del catálogo, rareza, cantidad y si es único. Configura premios para todas las rarezas antes de habilitar la ruleta. Revisa el precio y máximo de tiradas en sus reglas. Las tiradas normales descuentan el coste y entregan el premio automáticamente; no requieren intervención.",{"group":"Economía","roles":[],"requires":["wallet:data:content","spin:action:spinRewardEdit","settings:action:ruleConfig"]}],["Revisar premios legendarios","En Zenis e inventario localiza Recompensas pendientes. Abre el premio legendario, comprueba el personaje, objeto y circunstancias de la tirada. Selecciona Aprobada o Rechazada e indica el motivo. Si apruebas, se incorpora al inventario; no lo añadas manualmente otra vez. Si no corresponde resolverlo con tus permisos, sigue la guía de escalado.",{"group":"Economía","roles":[],"requires":["wallet:data:content","spin:action:spinApprove"]}],["Revisar objetos únicos repetidos no legendarios","En Recompensas pendientes abre el objeto único repetido. Comprueba si ya existe en el inventario o en otra revisión y decide según las reglas. Guarda el estado y el motivo. No repitas la concesión si ya fue aprobada.",{"group":"Economía","roles":[],"requires":["wallet:data:content","spin:action:spinApproveUnique"]}],["Modificar saldos","En Zenis e inventario utiliza el control de saldo del usuario autorizado. Verifica la cuenta, el importe que corresponde y el saldo resultante antes de confirmar. Escribe un motivo que identifique la recompensa, corrección o evento. No repitas una operación ya aplicada.",{"group":"Economía","roles":[],"requires":["wallet:action:balance"]}],["Administrar inventarios","Desde Zenis e inventario selecciona la cuenta o personaje correcto. Utiliza la edición de inventario para registrar los objetos autorizados, su cantidad y estado. Comprueba duplicados y la justificación del cambio. No utilices la edición manual para duplicar un premio de Spin o sorteo.",{"group":"Economía","roles":[],"requires":["wallet:action:inventory","wallet:action:itemEdit"]}],["Interpretar alertas de tiradas","Consulta las alertas en Zenis e inventario y revisa el contexto de la actividad antes de intervenir. Una racha de rarezas altas es una señal para revisar, no prueba de abuso. Conserva la evidencia y actúa según el procedimiento de moderación aplicable.",{"group":"Economía","roles":[],"requires":["wallet:data:spinAlerts"]}],["Crear y editar encuestas","En Encuestas pulsa Crear encuesta. Introduce título, descripción, imagen opcional, fecha de cierre y al menos dos opciones (una por línea). Comprueba que la pregunta sea clara. Si ya hay votos, evita cambiar el significado de las opciones. Los porcentajes se calculan a partir de los votos registrados.",{"group":"Comunidad","roles":[],"requires":["polls:action:eventEdit"]}],["Cerrar o retirar encuestas","Cuando termine el plazo, utiliza Cerrar si corresponde. Comprueba los resultados y no elimines una encuesta que deba conservarse como referencia.",{"group":"Comunidad","roles":[],"requires":["polls:action:eventClose","polls:action:remove"]}],["Crear sorteos y elegir ganadores","En Sorteos crea el evento con título, descripción, imagen, cierre y número de ganadores. Si corresponde, configura Zenis por ganador o acceso a una raza exclusiva. Una vez cerrado y verificados los requisitos, pulsa Sortear ganadores y comprueba el resultado. No repitas el sorteo para elegir otro ganador por preferencia personal.",{"group":"Comunidad","roles":[],"requires":["draws:action:eventEdit","draws:action:drawWinners"]}],["Publicar y mantener anuncios","En Anuncios utiliza Publicar o Editar. Añade título, descripción e información con los bloques disponibles: títulos, texto, imágenes, listas y enlaces. Revisa la presentación antes de guardar. Ordena las publicaciones y retira contenido que ya no corresponda.",{"group":"Comunidad","roles":[],"requires":["announcements:action:contentEdit","announcements:action:recordMove","announcements:action:remove"]}],["Cambiar el estado de una sugerencia","Abre Sugerencias, pulsa Cambiar estado, selecciona el nuevo estado y escribe el motivo. Si procede añade un comentario público. El historial muestra el autor, fecha y transición; no lo uses para conversaciones privadas.",{"group":"Comunidad","roles":[],"requires":["suggestions:action:suggestReview"]}],["Consultar votantes y eliminar sugerencias","Usa Ver votos solo cuando una revisión lo requiera. No difundas datos de votantes fuera de la gestión autorizada. Antes de eliminar una sugerencia comprueba el contexto y justifica la decisión.",{"group":"Comunidad","roles":[],"requires":["suggestions:action:voteList","suggestions:action:remove"]}],["Cambiar moneda y límites por usuario","En Configuración edita el nombre de la moneda y los límites de cada tipo de registro. Define el máximo total, máximo por periodo y duración del periodo según la necesidad. Guarda con motivo. Los valores de límite cero representan ausencia de ese límite. No reduzcas límites sin valorar los registros existentes.",{"group":"Configuración","roles":[],"requires":["settings:action:settingsSave"]}],["Configurar las reglas del rol","En Configuración pulsa Configurar reglas. Ajusta el equilibrio de reparto si se utiliza, el límite de estadísticas y el divisor de ganancias. Introduce valores coherentes y el motivo; verifica el efecto sobre los cálculos. No actives el equilibrio si el reglamento lo mantiene desactivado.",{"group":"Configuración","roles":[],"requires":["settings:action:ruleConfig"]}],["Configurar talentos y probabilidades","En Configuración abre Configurar talentos. Añade o elimina talentos, edita sus nombres y descripciones, y asigna probabilidades entre 0 y 100. La suma debe ser exactamente 100 %. Los resultados ya guardados no se vuelven a tirar por cambiar la configuración.",{"group":"Configuración","roles":[],"requires":["settings:action:talentConfig"]}],["Gestionar las sagas","Abre Historial de sagas. Inicia una saga con nombre, información y reglas aplicables; modifica su información o finalízala cuando corresponda. Los cambios de reglas durante una saga generan una nueva revisión histórica. Consulta el contexto de los informes antiguos antes de ajustar sus recompensas.",{"group":"Configuración","roles":[],"requires":["sagas:action:sagaStart","sagas:action:sagaEdit","sagas:action:sagaFinish"]}],["Identidad visual y apariencia","En Configuración modifica el nombre de la web, fuente, fondo y colores de paneles, superficies, bordes, texto, acento y enlaces. Comprueba que el contraste y la legibilidad sean adecuados. Guarda con motivo.",{"group":"Configuración","roles":[],"requires":["settings:action:settingsSave","settings:data:fullSettings"]}],["Registro, invitaciones y mantenimiento","En Configuración decide si se admiten registros y si requieren código. Gestiona los códigos y el rol predeterminado de nuevas cuentas. Activa mantenimiento cuando sea necesario e introduce un mensaje comprensible. Comprueba que los cambios no impidan acceder a quienes deban trabajar.",{"group":"Configuración","roles":[],"requires":["settings:action:settingsSave","settings:data:fullSettings"]}],["Presencia y política de contraseña","En Configuración ajusta el intervalo de presencia y el tiempo para considerar una sesión inactiva. En Configurar reglas establece los límites de longitud de contraseña si procede. Valora el efecto sobre la experiencia de acceso.",{"group":"Configuración","roles":[],"requires":["settings:action:settingsSave","settings:action:ruleConfig","settings:data:fullSettings"]}],["Crear y ordenar categorías y páginas","Abre Organización y páginas. Añade categorías de navegación para agrupar apartados, crea páginas y utiliza los controles de movimiento para ordenar categorías y páginas o cambiarlas de grupo. Comprueba la navegación con el acceso que corresponda. No crees un apartado duplicado si puedes reorganizar uno existente.",{"group":"Organización","roles":[],"requires":["categories:action:navGroupEdit","categories:action:navPageMove","categories:action:navGroupMove"]}],["Editar información de una página","En Organización y páginas selecciona la página que quieras crear o editar. Define su nombre y descripción, añade bloques de título, texto, lista, imagen o enlace, y ordénalos. Comprueba el contenido y el acceso antes de guardarlo.",{"group":"Organización","roles":[],"requires":["categories:action:navPageEdit"]}],["Categorías internas de catálogos y tienda","En Organización y páginas utiliza las categorías internas para agrupar entradas del catálogo o productos. Crea y ordena categorías y subcategorías; antes de eliminar una comprueba que no tenga entradas dependientes.",{"group":"Organización","roles":[],"requires":["categories:action:categoryEdit","categories:action:categoryMove","categories:action:categoryDelete"]}],["Modificar el molde de un formulario","Abre Moldes de formularios y selecciona el formulario. Añade apartados y campos, define tipo, opciones, ayuda y obligatoriedad. En las fichas decide si el campo lo rellena el jugador, solo durante la creación, o el Staff. Los cambios se aplican a fichas existentes; los campos nuevos quedan vacíos hasta rellenarlos. No sustituyas campos de sistema por textos libres.",{"group":"Organización","roles":[],"requires":["schemas:action:sectionEdit","schemas:action:fieldEdit"]}],["Reordenar, mover y eliminar campos","Usa las flechas para cambiar el orden y Mover para transferir un campo a otro apartado. Elimina campos únicamente si dejan de ser necesarios. Los valores antiguos pueden quedar almacenados aunque el campo ya no aparezca. Comprueba las fichas existentes tras modificar el molde.",{"group":"Organización","roles":[],"requires":["schemas:action:schemaMove","schemas:action:fieldTransfer","schemas:action:schemaDelete"]}],["Configurar estados de revisión","En Estados selecciona el tipo de registro. Crea o edita el nombre, color y efecto del estado (aprobación, rechazo o sin efecto). Ordena los estados y no elimines uno que siga en uso. Un estado con efecto de aprobación puede activar consecuencias del sistema: revisa su significado antes de cambiarlo.",{"group":"Organización","roles":[],"requires":["states:action:stateEdit","states:action:stateMove","states:action:stateDelete"]}],["Consultar roles y permisos","En Roles y permisos pulsa Consultar permisos junto al rol. Acceso permite abrir una página; Datos visibles determina qué información muestra; Mostrar controla los botones; Ejecutar permite realizar las acciones autorizadas. Utiliza esta consulta para identificar quién puede resolver una petición.",{"group":"Equipo","roles":[],"requires":["roles:action:roleView"]}],["Crear, editar y ordenar roles","En Roles y permisos crea o edita un rol no protegido. Define su nombre, color y jerarquía; configura acceso, datos, permisos generales y acciones individuales. La visibilidad no equivale a permiso de ejecución. Prueba cada cambio con una cuenta de ese rango. No concedas capacidades fuera de la responsabilidad del rango.",{"group":"Equipo","roles":[],"requires":["roles:action:roleEdit","roles:action:roleMove"]}],["Eliminar roles","Antes de eliminar un rol, retíralo de los usuarios y comprueba que no sea el rol predeterminado. Revisa la jerarquía y justifica la eliminación. No se puede eliminar el rol protegido del Owner.",{"group":"Equipo","roles":[],"requires":["roles:action:roleDelete"]}],["Consultar nombres, roles y presencia","En Usuarios puedes consultar el nombre, los roles y el indicador Online/Offline. Úsalo para identificar al usuario y comprobar su presencia. Offline no significa que la cuenta esté sancionada.",{"group":"Cuentas","roles":[],"requires":["users:data:name","users:data:roles","users:data:presence"]}],["Consultar la actividad de una cuenta","En Usuarios abre los detalles autorizados de la cuenta. Consulta la última conexión y actividad, y contrasta el contexto si investigas una incidencia. Los registros de presencia son orientativos; no demuestran por sí solos quién utiliza la cuenta.",{"group":"Cuentas","roles":[],"requires":["users:action:userDetail","users:data:lastLogin","users:data:activity"]}],["Consultar dispositivos y sesiones","En los detalles autorizados consulta el navegador, sistema, dispositivo y apartado actual. Compara fechas y contexto; un cambio de navegador o dispositivo no constituye una infracción por sí solo. Trata esta información como privada.",{"group":"Cuentas","roles":[],"requires":["users:action:userDetail","users:data:device","users:data:browser","users:data:location"]}],["Asignar roles a usuarios","En Usuarios localiza la cuenta y pulsa Roles. Asigna o retira los roles correspondientes respetando la jerarquía. Comprueba que el resultado coincide con el nombramiento aprobado y registra el motivo.",{"group":"Cuentas","roles":[],"requires":["users:action:userRoles"]}],["Sancionar o levantar sanciones","En Usuarios selecciona la cuenta que puedas gestionar. Pulsa Sancionar, elige advertencia o suspensión y establece el fin si corresponde. Escribe un motivo concreto. Para retirar una medida utiliza Retirar sanción cuando esté justificado. No sanciones a partir de una sospecha sin contrastar.",{"group":"Cuentas","roles":[],"requires":["users:action:sanction","users:action:unsanction","users:data:sanctions"]}],["Habilitar o deshabilitar cuentas","Usa Habilitar o Deshabilitar en Usuarios para una medida de acceso autorizada. Comprueba primero el usuario afectado y el motivo. No confundas esta acción con una suspensión temporal ni la uses para evitar el procedimiento habitual.",{"group":"Cuentas","roles":[],"requires":["users:action:toggleUser"]}],["Gestionar contraseñas ajenas","Tras completar el protocolo de ticket, contrasta la información disponible con las respuestas del usuario. Valora el conjunto de indicios y solicita aclaraciones si son insuficientes. En Usuarios abre la gestión de contraseña de la cuenta correcta. Genera una temporal o establece una nueva autorizada, guarda el motivo y entrega la temporal en privado. El usuario deberá cambiarla al acceder. No compartas los datos usados para verificar la identidad.",{"group":"Cuentas","roles":["owner"],"requires":["users:action:userPassword"]}],["Renombrar y eliminar cuentas","En Usuarios utiliza Renombrar o Eliminar únicamente cuando la solicitud esté autorizada. Comprueba el identificador de cuenta, fichas y consecuencias antes de confirmar. Justifica el cambio y extrema la precaución ante una eliminación irreversible.",{"group":"Cuentas","roles":["owner"],"requires":["users:action:renameUser","users:action:deleteUser"]}],["Consultar y filtrar registros","Abre Registros. Combina fecha y hora inicial/final, autor, tipo de acción, módulo y búsqueda por texto. Abre Antes / después para consultar los cambios de datos autorizados. Comprueba el autor, fecha, motivo y campos afectados al investigar una incidencia.",{"group":"Auditoría","roles":[],"requires":["logs:data:content","logs:data:detail","logs:action:logView"]}],["Deshacer una operación","Localiza el registro y comprueba sus cambios anteriores y posteriores. Utiliza Deshacer solo si aparece disponible y no sobrescribe modificaciones posteriores. Indica el motivo. Si la reversión no es posible, documenta el problema y utiliza el procedimiento autorizado de corrección; nunca fuerces una reversión destructiva.",{"group":"Auditoría","roles":[],"requires":["logs:action:undo","logs:data:detail"]}],["Eliminar registros","Filtra el historial si es necesario, selecciona los registros que realmente deseas borrar y utiliza Borrar seleccionados. Borrar todo elimina el historial completo. Los registros no caducan automáticamente; verifica el alcance y conserva una copia si procede antes de confirmar.",{"group":"Auditoría","roles":["owner"],"requires":["logs:action:deleteLogs"]}],["Consultar datos y consumo","En Datos y consumo revisa las lecturas, escrituras y eliminaciones diarias estimadas y los registros almacenados por colección. Compara con los límites gratuitos mostrados; son estimaciones locales, no cifras reales de Firebase ni importes monetarios. Investiga aumentos de actividad antes de aplicar medidas.",{"group":"Auditoría","roles":[],"requires":["data:data:content"]}],["Crear una copia de seguridad","En Copias de seguridad pulsa Descargar copia y conserva el archivo en un lugar privado. Identifica su fecha y no lo compartas con jugadores. Las copias pueden contener información sensible; comprueba su alcance antes de compartirlas.",{"group":"Auditoría","roles":[],"requires":["backups:action:backup"]}],["Restaurar una copia","Antes de restaurar, conserva una copia actual y comprueba la fecha y origen del archivo. Selecciona el archivo JSON y revisa el aviso que indica qué datos se reemplazarán o conservarán. Confirma solo si entiendes el alcance; la operación puede cerrar la sesión.",{"group":"Auditoría","roles":[],"requires":["backups:action:restore"]}],["Editar los FAQ por perfil","Pulsa Editar preguntas. Selecciona la sección, escribe la pregunta y respuesta, y define los perfiles destinatarios y los requisitos de acceso, dato o acción. Una pregunta con varios requisitos solo aparece si todos se cumplen. Usa la previsualización por rol para comprobar que no revela funciones ajenas. Solo el Owner puede guardar estos cambios.",{"group":"Manual","roles":["owner"],"requires":["faqStaff:action:faqEdit"]}],["Qué comprobar antes de aprobar una ficha","Comprueba que no falte información obligatoria, que la raza y variante sean compatibles y que el lore no contradiga las reglas. Suma Fuerza, Velocidad, Resistencia y Ki y contrasta el máximo inicial aplicable. Revisa que las habilidades iniciales y el tipo de ki correspondan. Si algo no cuadra, deja una nota concreta y no apruebes hasta que se corrija.",{"group":"Personajes","roles":[],"requires":["sheets:action:review","sheets:data:stats","sheets:data:status"]}],["Qué hacer con una ficha que necesita correcciones","Usa Revisar, selecciona un estado de revisión o rechazo según corresponda e indica en la nota visible los cambios concretos que necesita el jugador. No uses el estado de aprobación para una ficha incompleta. Cuando se corrija, comprueba los nuevos datos antes de aprobar.",{"group":"Personajes","roles":[],"requires":["sheets:action:review","sheets:data:status"]}],["Comprobar entrenamientos narrativos y combates","Comprueba el método seleccionado y sus requisitos: duración, turnos, participación, resultado o extensión narrativa, según corresponda. Lee la evidencia y verifica que corresponda al personaje y al periodo declarado. Elige una recompensa que se ajuste a los hechos, sin premiar el mismo entrenamiento por duplicado.",{"group":"Entrenamientos","roles":[],"requires":["training:action:review","training:data:details"]}],["Repartir las ganancias correctamente","Los campos de ganancia representan puntos adicionales, no el nuevo valor total. Si un personaje tenía 20 de Fuerza y concedes 5, su Fuerza resultante será 25. Comprueba que la suma de las cuatro ganancias sea la autorizada y que el resultado de la vista previa coincida antes de guardar.",{"group":"Entrenamientos","roles":[],"requires":["training:action:review","training:data:details"]}],["Cómo comunicar una revisión al jugador","Utiliza la nota visible para explicar qué se aprobó, qué debe corregir o por qué no procede aprobarlo. Escribe el motivo administrativo que solicite el formulario. No compartas la ganancia sugerida privada ni prometas una recompensa antes de finalizar la revisión.",{"group":"Entrenamientos","roles":[],"requires":["training:action:review","training:data:details"]}],["Configurar precio y límite del Spin","En Configuración abre Configurar reglas y establece el coste de Spin y máximo de tiradas por ficha. Un coste sin definir mantiene la ruleta no disponible y un máximo de cero no impone un límite de tiradas. Comprueba los premios configurados y el coste antes de habilitarlo.",{"group":"Configuración","roles":[],"requires":["settings:action:ruleConfig","spin:action:spinRewardEdit"]}],["Configurar diferencias de poder","En Configurar reglas introduce cinco multiplicadores de comparación separados por comas. Deben ser positivos y estar ordenados de menor a mayor. Comprueba que las categorías representen correctamente las diferencias de poder del reglamento.",{"group":"Configuración","roles":[],"requires":["settings:action:ruleConfig","compare:action:compare"]}],["Renombrar un apartado de navegación","En Organización y páginas usa la opción para editar el nombre de un apartado. Introduce un nombre claro y revisa que la navegación siga siendo entendible. Renombrar un apartado no cambia las reglas del sistema que contiene.",{"group":"Organización","roles":[],"requires":["categories:action:navEdit"]}],["Retirar una página o apartado","En Organización y páginas utiliza Eliminar solo para contenido que deba desaparecer. Comprueba los enlaces y referencias antes de confirmar. Los apartados del sistema no deben tratarse como páginas informativas desechables.",{"group":"Organización","roles":[],"requires":["categories:action:navDelete"]}],["Retirar una raza de la selección","Edita su disponibilidad para impedir nuevas selecciones sin borrar información existente. Para eliminar definitivamente una definición racial, comprueba antes que ninguna ficha la utilice.",{"group":"Catálogos y razas","roles":[],"requires":["catalogs:action:raceConfig","catalogs:action:configDelete"]}],["Cerrar o retirar sorteos","Usa Cerrar si quieres impedir nuevas participaciones. Verifica el resultado antes de retirar un sorteo y no elimines información necesaria para resolver reclamaciones sobre el premio.",{"group":"Comunidad","roles":[],"requires":["draws:action:eventClose","draws:action:remove"]}],["Previsualizar el manual de otro rango","En cualquiera de los FAQ selecciona un rol en Previsualizar como rol. Verás las preguntas que cumplen sus permisos actuales y sus destinatarios, sin cambiar la sesión ni los roles de tu cuenta. Prueba también los perfiles con acceso limitado después de modificar sus permisos.",{"group":"Manual","roles":["owner"],"requires":["faqStaff:action:faqEdit"]}]]};

function faqProfile(u=me){if(!u)return '';return ['owner','coowner','admin','verifier'].find(id=>u.roles.includes(id))||(u.roles.includes('member')&&!u.roles.some(id=>id!=='member'&&db.roles.find(r=>r.id===id)?.perms?.faqStaff?.view)?'member':'@custom')}
function faqActionAllowed(k,key){if(['dataBrowse','dataEdit','orphanDelete'].includes(key)&&!isOwner())return false;if(['bugApprove','bugStatus','bugDelete'].includes(key)&&!isOwner())return false;if(['inviteEdit','inviteView','inviteToggle','inviteDelete'].includes(key)&&!settingsFull())return false;if(isOwner())return true;if(!allow(k)||!dataAllowed(k,'actions')||(!['sheets','training','users'].includes(k)&&!dataAllowed(k,'content')))return false;if(['renameUser','userPassword','deleteUser','deleteLogs','selectLogs','faqEdit'].includes(key))return false;let def=controlsFor(k).find(d=>d[0]===key);if(!def)return false;return me.roles.some(id=>{let p=db.roles.find(r=>r.id===id)?.perms?.[k];if(!p?.view)return false;let perm=def[2],base=!!p[perm]||(['edit','delete'].includes(perm)&&!!p.manage),c=p.controls?.[key];return base&&(c?.execute??true)&&(c?.visible??base)})}
function faqRequirement(req){let match=/^(.+):(data|action|perm):(.+)$/.exec(req),k=match?match[1]:req,t=match?.[2],key=match?.[3];if(!k||!allow(k))return false;if(!t)return k==='users'||k==='sheets'||k==='training'||dataAllowed(k,'content');if(t==='data')return (['sheets','training','users'].includes(k)||dataAllowed(k,'content'))&&dataDefinitions(k).some(([id])=>id===key)&&dataAllowed(k,key);if(t==='action')return faqActionAllowed(k,key);if(t==='perm')return allow(k,key);return false}
function faqEligible(k,row){if(!me||!allow(k)||!dataAllowed(k,'content')||k==='faqStaff'&&isOwner())return false;let meta=row[2];if(!meta||!Array.isArray(meta.roles)||!Array.isArray(meta.requires))return isOwner();if(meta.roles.length&&!meta.roles.includes(faqProfile()))return false;if(meta.roles.includes('owner')&&meta.roles.length===1&&!isOwner())return false;return meta.requires.every(faqRequirement)}
function faqRows(k){return (db.faqs[k]||[]).filter(row=>faqEligible(k,row))}
function faqGroups(rows){let groups=new Map();for(let row of rows){let group=row[2]?.group||'General';if(!groups.has(group))groups.set(group,[]);groups.get(group).push(row)}return [...groups]}
