function undo(id){let l=db.logs.find(x=>x.id===id);if(!l?.patches)return old14_undo(id);if(!requirePerm('logs','undo')||!canUndo(l)||!isOwner()&&!safeUndo(l))return toast('La reversión no está disponible.');withReason('Deshacer: '+l.action,r=>{if(!canUndo(l)||!isOwner()&&!safeUndo(l))throw Error('Los datos han cambiado.');let roots=[...new Map(l.patches.map(p=>[JSON.stringify(p.path),p.path])).values()];let ok=commit14(roots,vals=>{for(let i=0;i<roots.length;i++){let ps=l.patches.filter(p=>same14(p.path,roots[i])),arr=vals[i];for(let p of ps.filter(x=>!x.order)){if(p.id===undefined){vals[i]=clone14(p.b);continue}let j=arr.findIndex(x=>x.id===p.id);if(p.b===undefined){if(j>=0)arr.splice(j,1)}else if(j>=0)arr[j]=p.redacted?{...arr[j],...clone(p.b)}:clone(p.b);else arr.splice(Math.min(p.bi??arr.length,arr.length),0,clone(p.b))}let order=ps.find(x=>x.order);if(order)arr.sort((a,b)=>order.b.indexOf(a.id)-order.b.indexOf(b.id))}},'Reversión de '+l.action,r);if(ok){db.logs.find(x=>x.id===id).undone=true;save()}return ok})}
// Safe expression parser: arithmetic, comparisons, boolean conditions and whitelisted functions.
function formula14(src,vars){if(typeof src!=='string'||src.length>500)throw Error('Fórmula vacía o demasiado larga.');let toks=src.match(/\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|[A-Za-z_][A-Za-z_0-9]*|>=|<=|==|!=|&&|\|\||[()+*/%<>,!\-]/g)||[];if(toks.join('')!==src.replace(/\s/g,'')||toks.length>200)throw Error('Símbolo no permitido.');let i=0,prec={'||':1,'&&':2,'==':3,'!=':3,'<':4,'>':4,'<=':4,'>=':4,'+':5,'-':5,'*':6,'/':6,'%':6};function atom(){let t=toks[i++];if(t==='('){let a=expr(0);if(toks[i++]!==')')throw Error('Falta cerrar paréntesis.');return a}if(['-','+','!'].includes(t)){let a=atom();return v=>t==='-'?-a(v):t==='!'?+!a(v):+a(v)}if(/^\d/.test(t||''))return ()=>+t;if(!t)throw Error('Expresión incompleta.');if(toks[i]==='('){i++;let args=[];if(toks[i]!==')'){do{args.push(expr(0));if(toks[i]!==',')break;i++}while(true)}if(toks[i++]!==')')throw Error('Falta cerrar función.');let valid={min:[1,20],max:[1,20],round:[1,2],abs:[1,1],floor:[1,1],ceil:[1,1],if:[3,3]}[t];if(!valid||args.length<valid[0]||args.length>valid[1])throw Error('Función o argumentos inválidos: '+t);return v=>{if(t==='if')return args[0](v)?args[1](v):args[2](v);let n=args.map(a=>a(v));if(t==='round'){let d=n[1]??0;if(!Number.isInteger(d)||d<0||d>8)throw Error('Precisión de redondeo inválida.');return Math.round(n[0]*10**d)/10**d}return Math[t](...n)}}if(!Object.hasOwn(vars,t))throw Error('Variable desconocida: '+t);return v=>v[t]}
function expr(min){let left=atom();while(prec[toks[i]]>=min){let op=toks[i++],right=expr(prec[op]+1),a=left;left=v=>{let x=a(v);if(op==='&&')return +(!!x&&!!right(v));if(op==='||')return +(!!x||!!right(v));let y=right(v);switch(op){case '+':return x+y;case '-':return x-y;case '*':return x*y;case '/':return x/y;case '%':return x%y;case '<':return +(x<y);case '>':return +(x>y);case '<=':return +(x<=y);case '>=':return +(x>=y);case '==':return +(x===y);case '!=':return +(x!==y)}}}return left}let tree=expr(1);if(i!==toks.length)throw Error('Expresión inválida.');let result=tree(vars);if(!Number.isFinite(result)||Math.abs(result)>1e15)throw Error('Resultado no finito o fuera de rango.');return result}
function gainVars(s,m,l,h,outcome){let combat=m.group==='combat';return {base:calc15('trainingBase',{combat:+combat,defeat:+(outcome==='Derrota'),loss:+m.loss||0,gain:+m.gain||0,hours:+h}),hours:h,gain:m.gain,loss:m.loss||0,methodMultiplier:m.multiplier,locationMultiplier:combat?l.combat:l.multiplier,raceBonus:variantOf(s)?.bonus||0,power:power(s),softCap:db.settings.rules.softCap,divisor:db.settings.rules.divisor,combat:+combat,defeat:+(outcome==='Derrota')}}
function estimate(s,m,l,h,outcome){let result=calc15('training',gainVars(s,m,l,h,outcome));if(result<0)throw Error('La fórmula produce una recompensa negativa.');return result}
function exampleVars(){return {base:20,hours:2,gain:10,loss:10,methodMultiplier:1,locationMultiplier:1,raceBonus:0,power:100,softCap:db.settings.rules.softCap,divisor:db.settings.rules.divisor,combat:0,defeat:0}}
const FORMULA_LABELS={base:'Ganancia base',hours:'Horas',gain:'Ganancia por hora / victoria',loss:'Ganancia por derrota',methodMultiplier:'Multiplicador del método',locationMultiplier:'Multiplicador del lugar',raceBonus:'Bonificación racial',power:'Poder actual',softCap:'Límite de estadísticas',divisor:'Divisor al alcanzar límite',combat:'Combate (0/1)',defeat:'Derrota (0/1)'};
function formulaForm(edit){let vars=exampleVars();dialog(edit?'Editor de fórmulas de entrenamiento':'Vista previa de cálculos',`<div class="sub"><p>La fórmula calcula los puntos sugeridos. El Staff conserva la decisión final. Operadores: +, −, *, /, %, comparaciones, &&, ||. Funciones: min, max, abs, round, floor, ceil, if(condición, sí, no).</p></div>${field('Fórmula de ganancia','formula','textarea',db.settings.formulas.training,true)}<h3>Valores de prueba (no modifican fichas)</h3><div class="grid">${Object.entries(vars).map(([k,v])=>field(FORMULA_LABELS[k]+' · '+k,'test_'+k,'number',v,true)).join('')}</div><div class="card"><small>Resultado de la simulación</small><div id="calc-output" class="calc-result"></div><p id="calc-error" class="error"></p></div>${edit?reasonField():''}`,edit?f=>{if(!allow('settings','manage')||!controlAllowed('formulaEdit',[]))throw Error('Sin permiso.');let v=Object.fromEntries(Object.keys(vars).map(k=>[k,+f['test_'+k]]));for(let test of [v,{...v,power:0},{...v,power:v.softCap+1},{...v,combat:1,defeat:1,base:v.loss}])if(formula14(f.formula,test)<0)throw Error('La recompensa no puede ser negativa.');return mutate(['settings','formulas'],a=>a.training=f.formula,'Fórmula de ganancias modificada',f.reason)}:null,{wide:true,bind:root=>{let refresh=()=>{let f=formValues(root.querySelector('form'));try{let n=formula14(f.formula,Object.fromEntries(Object.keys(vars).map(k=>[k,+f['test_'+k]])));if(n<0)throw Error('Resultado negativo.');root.querySelector('#calc-output').textContent=n.toLocaleString('es-ES')+' puntos';root.querySelector('#calc-error').textContent=''}catch(e){root.querySelector('#calc-output').textContent='—';root.querySelector('#calc-error').textContent=e.message}};root.querySelector('form').addEventListener('input',refresh);refresh()}})}
function formulaEdit(){if(requirePerm('settings','manage'))formulaForm15(true)}function formulaPreview(){if(allow('settings'))formulaForm15(false)}
function settingsPage(){return old14_settingsPage()+`<div class="card"><h2>Fórmulas y simulación</h2><p class="muted">Editor general de cálculos del rol · selecciona una operación, prueba valores y guarda con motivo.</p>${permitted('settings','manage','Editar fórmulas','formulaEdit')}${btn('Probar cálculos','formulaPreview')}</div>`}
function day14(){return new Date().toISOString().slice(0,10)}
function countUsage(k,n=1,collection='system',action=false,label=''){if(!n||!db.monitor)return;let d=day14(),u=db.settings.usage[d]??={read:0,write:0,delete:0};u[k]=(u[k]||0)+n;let day=db.monitor.days[d]??={users:{},collections:{}};let user=day.users[String(me?.id||0)]??={read:0,write:0,delete:0,actions:0};let col=day.collections[collection]??={read:0,write:0,delete:0};user[k]+=n;col[k]+=n;if(action){user.actions++;let a=db.monitor.activity;a.push({user:me?.id||0,at:now(),action:label||'Acción',module:collection});let windowMs=db.settings.optimization.windowMinutes*60000;db.monitor.activity=a.filter(x=>Date.now()-Date.parse(x.at)<=windowMs);let recent=db.monitor.activity.filter(x=>x.user===me?.id);if(me&&recent.length>=db.settings.optimization.actionThreshold)monitorAlert('usage',String(me.id)+'/'+Math.floor(Date.now()/windowMs),{user:me.id,count:recent.length,window:db.settings.optimization.windowMinutes,actions:recent.slice(),totals:clone(user)})}let limits={read:50000,write:20000,delete:20000};if(u[k]>=limits[k]*db.settings.optimization.quotaPercent/100)monitorAlert('quota',d+'/'+k,{operation:k,total:u[k],limit:limits[k],day:d,user:me?.id||0})}
function monitorAlert(type,key,info){let prev=db.monitor.alerts.find(a=>a.type===type&&a.key===key);if(prev){if(!prev.reviewed){prev.info=info;prev.updated=now()}return}db.monitor.alerts.unshift({id:uid(),type,key,info,created:now(),updated:now(),reviewed:false})}
function detectSpin14(id){let n=db.settings.optimization.spinWindow,t=db.settings.optimization.spinHigh;for(let s of db.records.sheets){if(id&&s.id!==id)continue;let h=s.spinHistory||[];if(h.length<n)continue;let recent=h.slice(-n),hits=recent.filter(x=>['Épico','Legendario'].includes(x.rarity)).length;if(hits>=t)monitorAlert('spin',s.id+'/'+(h.length-n+1),{user:s.owner,sheet:s.id,name:recordName('sheets',s),hits,window:n,history:clone(recent),probability:spinTail14(recent,t)})}}
function spinTail14(history,t){let dp=[1];for(let h of history){let w=h.weights||RARITY_WEIGHTS,den=w.reduce((a,b)=>a+b,0),p=den?RARITIES.reduce((a,r,i)=>a+(['Épico','Legendario'].includes(r)?w[i]:0),0)/den:0;let next=Array(dp.length+1).fill(0);dp.forEach((v,i)=>{next[i]+=v*(1-p);next[i+1]+=v*p});dp=next}return dp.slice(t).reduce((a,b)=>a+b,0)}
function accountPageRead(k){if(!db.monitor||!me)return;let cache=db.monitor.cache??={},key=me.id+'|'+k,time=Date.now(),ttl=db.settings.optimization.cacheSeconds*1000;if(cache[key]&&time-cache[key]<ttl)return;cache[key]=time;let rows=db.records[k]|| (k==='users'?db.users:k==='logs'?db.logs:[]);countUsage('read',Math.max(1,Math.min(rows.length,db.settings.optimization.pageSize)),k,true,'Consulta de '+(NAMES[k]||k));save()}
function pendingBadge(k){if(!allow(k,'review')||!['sheets','training','races','bugs'].includes(k)||!dataAllowed(k,k==='bugs'?'content':'status'))return '';let n=(db.records[k]||[]).filter(r=>k==='bugs'?r.status==='Pendiente':!approved(k,r)&&!rejected(k,r)).length;return n?`<span class="nav-count" title="Pendientes de revisión">${n}</span>`:''}
function sideLabel(k,n,items){return old14_sideLabel(k,n,items)}
function bindPagination(root){if(!root||!db.settings.optimization)return;let size=db.settings.optimization.pageSize;for(let t of root.querySelectorAll('.content .tablewrap')){if(t.nextElementSibling?.classList.contains('page-controls'))continue;let rows=[...t.querySelectorAll('tbody tr')];if(rows.length<=size)continue;let page=0,ctrl=document.createElement('div');ctrl.className='page-controls';ctrl.innerHTML='<button type="button">Anterior</button><span></span><button type="button">Siguiente</button>';t.after(ctrl);let [prev,next]=ctrl.querySelectorAll('button'),text=ctrl.querySelector('span');let draw=()=>{let q=($('#filter')?.value||'').toLowerCase(),eligible=rows.filter(r=>r.textContent.toLowerCase().includes(q));page=Math.min(page,Math.max(0,Math.ceil(eligible.length/size)-1));let visible=new Set(eligible.slice(page*size,(page+1)*size));rows.forEach(r=>r.hidden=!visible.has(r));text.textContent=`${eligible.length} resultados · Página ${page+1} / ${Math.max(1,Math.ceil(eligible.length/size))}`;prev.disabled=page===0;next.disabled=(page+1)*size>=eligible.length};prev.onclick=()=>{page--;draw()};next.onclick=()=>{page++;draw();countUsage('read',Math.max(1,Math.min(size,rows.length-page*size)),view,true,'Página de '+(NAMES[view]||view));save()};$('#filter')?.addEventListener('input',()=>{page=0;draw()});draw()}}
function usageConfig(){if(!requirePerm('data','manage'))return;let o=db.settings.optimization,labels={cacheSeconds:'Caché estimada (segundos)',pageSize:'Registros por página',cooldown:'Cooldown de escritura (segundos; 0 desactiva)',windowMinutes:'Ventana de actividad (minutos)',actionThreshold:'Acciones por usuario para alerta',quotaPercent:'Aviso al alcanzar % de cuota diaria',spinWindow:'Tiradas de la ventana',spinHigh:'Premios épicos o legendarios en esa ventana'};dialog('Consumo y alertas',Object.entries(labels).map(([k,l])=>field(l,k,'number',o[k],true)).join('')+reasonField(),f=>{let n=Object.fromEntries(Object.keys(labels).map(k=>[k,+f[k]]));if(Object.values(n).some(x=>!Number.isInteger(x)||x<0)||n.pageSize<5||n.pageSize>200||n.windowMinutes<1||n.actionThreshold<1||n.quotaPercent<1||n.quotaPercent>100||n.spinWindow<2||n.spinWindow>100||n.spinHigh<1||n.spinHigh>n.spinWindow)throw Error('Parámetros inválidos.');return change(['settings','optimization'],n,'Configuración de consumo y alertas',f.reason)})}
function alertTitle(a){return a.type==='spin'?'Racha inusual de Spin':a.type==='quota'?'Cuota diaria elevada':'Actividad inusual de cuenta'}
function alertDetail(id){if(!allow('data')||!dataAllowed('data','content'))return;let a=db.monitor.alerts.find(x=>x.id===id);if(!a)return;let x=a.info,body=`<div class="card"><h2>${E(alertTitle(a))}</h2><p>${date(a.created)} · ${a.reviewed?'Revisada':'Pendiente'}</p><p>Cuenta: ${E(userName(x.user))}</p></div>`;if(a.type==='usage')body+=`<div class="card"><h3>${x.count} acciones en ${x.window} minutos</h3>${table(['Fecha','Acción'],x.actions.map(y=>[date(y.at),E(y.action)]))}<p>Lecturas: ${x.totals.read} · Escrituras: ${x.totals.write} · Eliminaciones: ${x.totals.delete}</p></div>`;if(a.type==='quota')body+=`<div class="card"><h3>${E(({read:'Lecturas',write:'Escrituras',delete:'Eliminaciones',worker:'Peticiones de Cloudflare'})[x.operation])}</h3><p>${x.total} de ${x.limit} · ${(100*x.total/x.limit).toFixed(1)} % · ${E(x.day)}</p></div>`;if(a.type==='spin')body+=`<div class="card"><h3>${E(x.name)}</h3><p>${x.hits} premios de rareza alta en ${x.window} tiradas. No demuestra manipulación; comprueba la secuencia y sus registros.</p>${Number.isFinite(x.probability)?`<p>Probabilidad orientativa de alcanzar el umbral en una ventana fija: ${(100*x.probability).toLocaleString('es-ES',{maximumSignificantDigits:4})} %.</p>`:''}${table(['Fecha','Premio','Rareza','Coste'],x.history.map(y=>[date(y.at),E(y.name),E(y.rarity),E(y.cost??'—')]))}</div>`;show(alertTitle(a),body)}
