function dataPage(){let d=day14(),detail=db.monitor.days[d]||{users:{},collections:{}},c=db.settings.usage[d]||{read:0,write:0,delete:0};return old14_dataPage()+`<div class="card"><h2>Control de consumo</h2><p class="muted">Actividad registrada por el servicio, separada de las cifras oficiales de Firebase y Cloudflare. La caché del servicio evita recargas de documentos mientras está activa.</p>${permitted('data','manage','Configurar consumo y alertas','usageConfig')}<h3>Por usuario · ${d}</h3>${table(['Cuenta','Lecturas','Escrituras','Eliminaciones','Acciones'],Object.entries(detail.users).sort((a,b)=>b[1].actions-a[1].actions).map(([id,v])=>[E(+id?userName(+id):'Sistema'),v.read,v.write,v.delete,v.actions]))}<h3>Por colección</h3>${table(['Colección','Lecturas','Escrituras','Eliminaciones'],Object.entries(detail.collections).map(([k,v])=>[E(NAMES[k]||k),v.read,v.write,v.delete]))}</div><div class="card"><h2>Alertas de uso y Spin · ${db.monitor.alerts.filter(a=>!a.reviewed).length} pendientes</h2>${table(['Fecha','Alerta','Cuenta','Estado','Acciones'],db.monitor.alerts.map(a=>[date(a.created),E(alertTitle(a)),E(userName(a.info.user)),a.reviewed?'Revisada':'Pendiente',btn('Detalles','alertDetail',[a.id])+(!a.reviewed?permitted('data','manage','Marcar revisada','alertAck',[a.id]):'')]))}</div>${isOwner()?`<div class="card"><h2>Gestión de datos</h2><p>Inspecciona registros y elimina valores de campos retirados del molde.</p>${btn('Explorar registros','dataBrowse')}${btn('Revisar datos huérfanos','orphanDelete')}</div>`:''}`}
