function globalSearch(){if(!me)return;dialog('Buscar en la web',`<div class="field"><label>Personajes, razas, técnicas, objetos o maestros</label><input id="global-query" placeholder="Escribe para buscar…" autocomplete="off"></div><div id="global-results" class="itemlist"></div>`,null,{wide:true,bind:root=>{let q=root.querySelector('#global-query'),out=root.querySelector('#global-results');let refresh=()=>{let val=q.value.trim().toLowerCase();if(!val){out.innerHTML='<p class="muted">Escribe al menos dos caracteres.</p>';return}if(val.length<2)return;let found=[];for(let k of ['sheets','races','raceDefinitions','catalogs','shop','teachers']){let mod=k==='raceDefinitions'?'catalogs':k;if(!allow(mod)||k==='sheets'&&!dataAllowed(k,'f_'+sf('name')?.id)||!['sheets','races'].includes(k)&&!dataAllowed(mod,'content'))continue;if(k==='races'){let f=db.schemas.races.flatMap(x=>x.fields).find(x=>x.key==='name'||x.label==='Nombre');if(f&&!dataAllowed(k,'f_'+f.id))continue}for(let r of db.records[k]||[]){let name=recordName(k,r);if(name.toLowerCase().includes(val))found.push({k,id:r.id,name,mod})}}out.innerHTML=found.slice(0,80).map(r=>`<div class="sub search-result"><div><b>${E(r.name)}</b><small>${E(NAMES[r.mod]||r.mod)}</small></div>${btn('Abrir','searchOpen',[r.k,r.id])}</div>`).join('')||empty('Sin resultados.');applyControlVisibility(out)};q.addEventListener('input',refresh);q.focus();refresh()}})}
function searchOpen(k,id){let mod=k==='raceDefinitions'?'catalogs':k;if(!allow(mod)||!record(k,id))return;if(k==='sheets'&&!dataAllowed('sheets','f_'+sf('name')?.id))return;if(k==='races'){let f=db.schemas.races.flatMap(x=>x.fields).find(x=>x.key==='name'||x.label==='Nombre');if(f&&!dataAllowed(k,'f_'+f.id))return}if(!['sheets','races'].includes(k)&&!dataAllowed(mod,'content'))return;$('#modal').innerHTML='';view=mod;render();if(['sheets','races'].includes(k)&&controlAllowed('formView',[k,id]))show(recordName(k,record(k,id)),recordDetail(k,record(k,id)));else if(k==='raceDefinitions'&&controlAllowed('raceInfo',[id]))raceInfo(id);else if(['catalogs','shop'].includes(k)&&controlAllowed('contentView',[k,id]))contentView(k,id)}
function dataBrowse(k='sheets'){if(!isOwner())return;let collections=Object.keys(db.records),rows=db.records[k]||[];show('Explorador de datos',`<div class="card"><h3>Colecciones</h3><div class="actions">${collections.map(x=>btn(NAMES[x]||x,'dataBrowse',[x],x===k?'primary':'')).join('')}</div></div><div class="card"><h3>${E(NAMES[k]||k)} · ${rows.length} registros</h3>${table(['Identificador','Registro','Acciones'],rows.map(r=>[E(r.id),E(r.title||r.name||recordName(k,r)),btn('Inspeccionar / editar','dataEdit',[k,r.id])]))}</div>`)}
function dataEdit(k,id){if(!isOwner())return;let r=record(k,id);if(!r)return;let safeKeys=new Set(['name','title','description','body','note','reviewNote','requirements','methodReq','locationReq','image','lore','text']);let keys=Object.keys(r).filter(x=>safeKeys.has(x)&&typeof r[x]==='string'),schemaFields=db.schemas[k]?.flatMap(s=>s.fields)||[],editableFields=schemaFields.filter(f=>!['stat','race','catalog','multiselect','select','number'].includes(f.type)&&['text','textarea','image','url'].includes(f.type)&&sheetMode(f)!=='staff');dialog('Datos · '+recordName(k,r),`<div class="card"><h3>Datos completos</h3><div class="data-tree">${auditValue(redact(r),k)}</div></div><div class="card"><h3>Corrección de contenido</h3><p class="muted">Identificadores, estadísticas, permisos, saldos y relaciones se modifican mediante sus editores específicos, para conservar las validaciones.</p>${keys.map(x=>field(auditLabel(x),'edit_'+x,x==='image'?'image':'textarea',r[x])).join('')}${editableFields.map(f=>field(f.label,'val_'+f.id,f.type,r.values?.[f.id]||'')).join('')||''}</div>${reasonField()}`,f=>mutate(['records',k],a=>{let n=a.find(x=>x.id===id);for(let x of keys)n[x]=f['edit_'+x];for(let fld of editableFields){n.values??={};n.values[fld.id]=f['val_'+fld.id]}},'Corrección de datos de '+recordName(k,r),f.reason),{wide:true})}
function orphanDelete(){if(!isOwner())return;let groups=[];for(let [k,schema] of Object.entries(db.schemas)){let ids=new Set(schema.flatMap(s=>s.fields.map(f=>f.id)));for(let r of db.records[k]||[]){let keys=Object.keys(r.values||{}).filter(x=>!ids.has(x));if(keys.length)groups.push({k,id:r.id,name:recordName(k,r),keys})}}dialog('Valores huérfanos',`<p class="muted">Estos valores pertenecen a campos eliminados del molde. Selecciona cuáles deseas borrar definitivamente.</p>${groups.map((g,i)=>`<div class="sub"><b>${E(g.name)} · ${E(NAMES[g.k])}</b>${g.keys.map((key,j)=>field(auditLabel(key)+' · '+String(record(g.k,g.id).values[key]).slice(0,100),'orphan_'+i+'_'+j,'checkbox',false)).join('')}</div>`).join('')||empty('No hay valores huérfanos.')}${groups.length?reasonField():''}`,groups.length?f=>{let selected=groups.map((g,i)=>({...g,keys:g.keys.filter((_,j)=>f['orphan_'+i+'_'+j])})).filter(g=>g.keys.length);if(!selected.length)throw Error('Selecciona los valores a eliminar.');let ks=[...new Set(selected.map(g=>g.k))];return commit14(ks.map(k=>['records',k]),a=>{for(let g of selected){let r=a[ks.indexOf(g.k)].find(x=>x.id===g.id);for(let key of g.keys)delete r.values[key]}},'Limpieza definitiva de valores huérfanos',f.reason,false)}:null,{wide:true})}
function upgrade14(d){if(d.version>=14)return;upgrade13(d);d.settings.initialStates??={};for(let [k,a] of Object.entries(d.states)){let pending=a.find(x=>!x.effect&&/pendiente/i.test(x.name))||a.find(x=>!x.effect);if(!pending){pending={id:uid(),name:'Pendiente',color:'#d5ad58',effect:''};a.push(pending)}d.settings.initialStates[k]=pending.id}d.settings.formulas??={training:DEFAULT_GAIN};d.settings.optimization??={cacheSeconds:120,pageSize:20,cooldown:0,windowMinutes:10,actionThreshold:40,quotaPercent:80,spinWindow:5,spinHigh:3};d.monitor??={days:{},alerts:[],activity:[],cache:{},lastMutation:{}};for(let r of d.roles){let staff=['admin','coowner'].includes(r.id);if(r.perms.settings){r.perms.settings.controls??={};r.perms.settings.controls.formulaEdit={visible:staff,execute:staff};r.perms.settings.controls.formulaPreview={visible:staff,execute:staff}}if(r.perms.data){r.perms.data.controls??={};for(let k of ['dataBrowse','dataEdit','orphanDelete'])r.perms.data.controls[k]={visible:false,execute:false}}}let add=(k,q,a,requires,links)=>{if(!d.faqs[k].some(r=>r[0]===q))d.faqs[k].push([q,a,{group:'Herramientas y revisión',roles:[],requires,links}])};add('faqUser','Buscar y consultar mi historial','Usa Buscar en la web para localizar personajes, razas, técnicas, objetos y maestros. Dentro de tu ficha, Historial del personaje muestra los entrenamientos aprobados y los puntos concedidos.', ['sheets'],['sheets']);add('faqStaff','Editar y probar la fórmula de ganancias','En Configuración, abre Fórmulas y simulación. Utiliza las variables descritas, operaciones aritméticas, min/max y condiciones if. Prueba ejemplos por debajo y por encima del límite de la saga, y combates con victoria o derrota. La fórmula cambia las sugerencias de informes nuevos; no recalcula los informes existentes. Guarda con motivo solo si coincide con el reglamento.', ['settings:action:formulaEdit'],['settings']);add('faqStaff','Revisar consumo y alertas','En Datos y consumo, revisa las lecturas, escrituras, eliminaciones y acciones estimadas por cuenta y colección. Abre cada alerta para comprobar la secuencia y los datos. Una racha rara no demuestra trampas: contrasta los registros antes de actuar. Marca revisada con motivo. Si se acerca el límite, revisa la configuración y aplica medidas proporcionadas; no etiquetes al Owner por una alerta ordinaria que puedas resolver.', ['data:action:alertDetail','data:action:alertAck'],['data','logs']);add('faqStaff','Configurar el estado inicial','El estado inicial se configura por separado del orden y debe ser neutro. En Estados configurables pulsa Usar como inicial junto al estado que deben recibir los registros nuevos. Reordenar la lista no cambia ese estado.', ['states:action:stateInitial'],['states']);add('faqStaff','Mantener variantes y revisar razas modificadas','Al editar una raza, usa las filas de variantes. El nombre puede cambiar sin perder el vínculo con personajes existentes. Las variantes referenciadas no se eliminan. Si el creador modifica una raza custom aprobada, debe volver a revisión antes de usarse en nuevas fichas. Las fichas existentes conservan su raza.', ['catalogs:action:raceConfig'],['catalogs','races']);d.version=14}


const FORMULAS15={"power":["Poder de pelea","Personajes","fuerza + velocidad + resistencia + ki",{"fuerza":25,"velocidad":25,"resistencia":25,"ki":25},"nonnegative"],"magicInitial":["Magia inicial","Personajes","base + bonus",{"base":5,"bonus":5},"percent"],"balanceLimit":["Máximo de equilibrio (si se activa)","Personajes","menor * ratio",{"menor":10,"ratio":1.6},"nonnegative"],"trainingBase":["Ganancia base de entrenamiento","Entrenamientos","if(combat, if(defeat, loss, gain), gain * hours)",{"combat":0,"defeat":0,"loss":10,"gain":10,"hours":2},"nonnegative"],"training":["Ganancia sugerida final","Entrenamientos","round(max(0, base * (methodMultiplier * locationMultiplier + raceBonus) / if(power >= softCap, divisor, 1)), 2)",{"base":20,"hours":2,"gain":10,"loss":10,"methodMultiplier":1,"locationMultiplier":1,"raceBonus":0,"power":100,"softCap":350,"divisor":1.5,"combat":0,"defeat":0},"nonnegative"],"allocation":["Reparto sugerido por estadística (primeras tres)","Entrenamientos","round(total / 4, 4)",{"total":20},"allocation"],"transformation":["Estadística transformada","Comparación","round(base * multiplier, 6)",{"base":100,"multiplier":2},"nonnegative"],"difference":["Diferencia B respecto a A","Comparación","b - a",{"a":100,"b":150},"number"],"ratio":["Multiplicador B respecto a A","Comparación","b / a",{"a":100,"b":150},"nonnegative"],"price":["Precio unitario con mercado y descuento","Economía","max(0, round(base * (1 + market / 100) * (1 - discount / 100)))",{"base":100,"market":10,"discount":20},"nonnegative"],"purchase":["Importe de compra","Economía","unit * quantity",{"unit":100,"quantity":3},"nonnegative"],"market":["Variación de evento económico","Economía","round(minimum + random * (maximum - minimum))",{"minimum":-10,"maximum":10,"random":0.5},"market"],"spinCost":["Coste efectivo del Spin","Spin","base",{"base":100,"power":100,"spins":0},"nonnegative"],"spinReward":["Cantidad de premio del Spin","Spin","quantity",{"quantity":1,"power":100,"rarity":4,"spins":0},"positiveInteger"],"spinWeight":["Peso de rareza del Spin","Spin","weight",{"weight":4,"rarity":4,"power":100,"spins":0},"nonnegative"],"talentWeight":["Peso de talento","Talentos","weight",{"weight":25,"index":1},"nonnegative"],"drawReward":["Zenis por ganador de sorteo","Economía","base",{"base":100,"participants":10,"winners":2},"nonnegative"],"trust":["Confianza resultante con maestro","Personajes","requested",{"current":25,"requested":50},"percent"]};

const formulaWarnings15=new Set();
function checkedFormula15(key,src,vars){let spec=FORMULAS15[key],n=formula14(src,vars),kind=spec[4];if((kind!=='number'&&kind!=='market'&&n<0)||(kind==='percent'&&n>100)||(kind==='positiveInteger'&&(!Number.isSafeInteger(n)||n<1))||(kind==='allocation'&&n>vars.total/3+1e-8)||(kind==='market'&&(n<vars.minimum||n>vars.maximum)))throw Error('Resultado incompatible con los límites de '+spec[0]+'.');return n}
function calc15(key,vars){let spec=FORMULAS15[key],src=db.settings.formulas?.[key]||spec[2];try{return checkedFormula15(key,src,vars)}catch(e){if(src===spec[2])throw e;if(!formulaWarnings15.has(key)){formulaWarnings15.add(key);console.warn('Fórmula inválida: '+key,e.message);toast('Fórmula inválida en '+spec[0]+'. Se aplica la fórmula predeterminada. Avisa al Staff.')}return checkedFormula15(key,spec[2],vars)}}
function power15(stats){return calc15('power',{fuerza:+stats[0]||0,velocidad:+stats[1]||0,resistencia:+stats[2]||0,ki:+stats[3]||0})}
function ratio15(a,b){return a===0?(b===0?1:Infinity):calc15('ratio',{a,b})}
function diff15(a,b){return calc15('difference',{a,b})}
function spinCost15(s){return db.settings.rules.spinCost==null?null:calc15('spinCost',{base:+db.settings.rules.spinCost,power:power(s),spins:s.spins||0})}
function spinWeights15(s){let weights=RARITY_WEIGHTS.map((weight,i)=>calc15('spinWeight',{weight,rarity:i+1,power:power(s),spins:s.spins||0}));if(!weights.some(w=>w>0))throw Error('La configuración de Spin no tiene pesos positivos.');return weights}
function percentage15(n,d){return d?100*n/d:0}
function formulaSamples15(key){let v=FORMULAS15[key][3],samples=[v];if(key==='training')samples.push({...v,power:0},{...v,power:v.softCap+1},{...v,combat:1,defeat:1,base:v.loss});if(key==='trainingBase')samples.push({...v,combat:1,defeat:1},{...v,combat:1,defeat:0});if(key==='spinWeight'||key==='spinReward')for(let rarity=1;rarity<=5;rarity++)samples.push({...v,rarity});if(key==='market')samples.push({...v,random:0},{...v,random:0.999999});return samples}
function formulaForm15(edit){if(!allow('settings')||edit&&(!allow('settings','manage')||!controlAllowed('formulaEdit',[])))return;let selected='training',values={};let body=`<div class="sub"><p>Selecciona la operación. Los cambios se aplican a cálculos futuros o derivados; las recompensas ya concedidas no se recalculan. Operadores: +, -, *, /, %, comparaciones, &&, ||. Funciones: min, max, abs, round, floor, ceil, if.</p><p class="muted">Los recuentos reales, saldos contables, límites de seguridad y generación aleatoria no se sustituyen por fórmulas editables.</p></div><label>Operación</label><select id="formula-choice">${Object.entries(FORMULAS15).map(([k,v])=>`<option value="${k}" ${k===selected?'selected':''}>${E(v[1]+' · '+v[0])}</option>`).join('')}</select><div id="formula-fields"></div><div class="card"><small>Resultado de la simulación</small><div id="calc-output" class="calc-result"></div><p id="calc-error" class="error"></p></div>${edit?reasonField():''}`;
 dialog(edit?'Editor general de fórmulas':'Vista previa de cálculos',body,edit?f=>{if(!allow('settings','manage')||!controlAllowed('formulaEdit',[]))throw Error('Sin permiso.');let k=selected,vars=Object.fromEntries(Object.keys(FORMULAS15[k][3]).map(v=>[v,Number(f['test_'+v])]));for(let test of [...formulaSamples15(k),vars])checkedFormula15(k,f.formula,test);formulaWarnings15.delete(k);return mutate(['settings','formulas'],a=>a[k]=f.formula,'Fórmula modificada · '+FORMULAS15[k][0],auditReason(f))}:null,{wide:true,bind:root=>{let choice=root.querySelector('#formula-choice'),fields=root.querySelector('#formula-fields');let refresh=()=>{let form=root.querySelector('form'),f=formValues(form);try{let n=checkedFormula15(selected,f.formula,Object.fromEntries(Object.keys(FORMULAS15[selected][3]).map(k=>[k,Number(f['test_'+k])])));root.querySelector('#calc-output').textContent=n.toLocaleString('es-ES',{maximumFractionDigits:8});root.querySelector('#calc-error').textContent=''}catch(e){root.querySelector('#calc-output').textContent='—';root.querySelector('#calc-error').textContent=e.message}};let draw=()=>{let spec=FORMULAS15[selected];fields.innerHTML=field('Fórmula','formula','textarea',db.settings.formulas?.[selected]||spec[2],true)+`<p class="muted">Predeterminada: ${E(spec[2])}</p><button type="button" id="reset-formula">Restablecer fórmula predeterminada</button><h3>Variables y valores de prueba</h3><div class="grid">${Object.entries(spec[3]).map(([k,v])=>field((FORMULA_LABELS[k]||k)+' · '+k,'test_'+k,'number',v,true)).join('')}</div>`;fields.querySelector('#reset-formula').onclick=()=>{fields.querySelector('[name=formula]').value=spec[2];refresh()};refresh()};choice.onchange=()=>{selected=choice.value;draw()};root.querySelector('form').addEventListener('input',refresh);draw()}})}
function upgrade15(d){upgrade14(d);d.settings.formulas??={};for(let [k,s] of Object.entries(FORMULAS15))if(!d.settings.formulas[k])d.settings.formulas[k]=s[2];if(d.version>=15)return;for(let f of d.faqs.faqStaff||[]){if(f[0]==='Editar y probar la fórmula de ganancias'){f[0]='Editar y probar las fórmulas del rol';f[1]='En Configuración, abre Fórmulas y simulación y selecciona una operación. Puedes modificar cálculos de poder, magia inicial, entrenamiento, transformaciones, comparación, precios, eventos económicos, Spin, talentos, sorteos y confianza. Usa los valores de prueba y comprueba los casos límite antes de guardar con motivo. Los cálculos históricos y las recompensas ya aplicadas se conservan. Si una fórmula falla en un caso real se usa la predeterminada y se muestra un aviso; corrige la fórmula. Los recuentos reales, el saldo contable, los permisos y la aleatoriedad no se pueden alterar desde el editor.';}}d.version=15}

