// Remote connection. The browser renders and sends intent, never submits a database snapshot.
const cloudEndpoint=()=>String(window.OMNI_API||'').replace(/\/$/,'');
const CLOUD_TOKEN='omni_cloud_token';let tokenCloud=sessionStorage.getItem(CLOUD_TOKEN)||'',cloudRev=0,cloudBusy=false,cloudTimer=null,cloudAction=null,cloudAuthInfo=null;
function cloudStatus(t,bad=false){let el=document.querySelector('#connection-state');if(!el){el=document.createElement('div');el.id='connection-state';el.style='position:fixed;bottom:12px;right:12px;padding:7px 12px;background:var(--panel);border:1px solid var(--border);border-radius:8px;font-size:12px;z-index:1100;pointer-events:none';document.body.append(el)}el.textContent=t;el.style.color=bad?'#f3a0a0':'var(--muted)'}
async function rpc(path,payload){if(!cloudEndpoint())throw Error('Falta configurar la URL del servicio.');let response=await fetch(cloudEndpoint()+path,{method:payload===undefined?'GET':'POST',headers:{...(tokenCloud?{Authorization:'Bearer '+tokenCloud}:{}),...(payload!==undefined?{'Content-Type':'application/json'}:{})},...(payload===undefined?{}:{body:JSON.stringify(payload)})});let result;try{result=await response.json()}catch{throw Error('El servicio no responde correctamente (HTTP '+response.status+').')}if(!response.ok){let e=Error(result.error||'Error HTTP '+response.status);e.status=response.status;throw e}return result}
function applyRemote(result){if(!result.state)return;let previous=me?.id;db=result.state;cloudRev=result.revision;me=db.users.find(x=>x.id===result.userId)||null;if(me&&!previous)view=firstView();if(result.workerUsage)db.workerUsage=result.workerUsage;}
function showTalent(){if(!me||me.temporary||db.settings.maintenance&&!isOwner())return;let pending=db.records.sheets.find(s=>s.owner===me.id&&!s.potential&&s.potentialChoices?.length);if(pending)potentialPick(pending.id)}
function notifyError(e){cloudStatus(e.message,true);toast(e.message);if(e.status===401){tokenCloud='';sessionStorage.removeItem(CLOUD_TOKEN);me=null;auth()}}
async function refreshCloud(force=false){if(!tokenCloud||cloudBusy||!force&&$('#modal')?.innerHTML)return;cloudBusy=true;try{let result=await rpc('/state');applyRemote(result);render();cloudStatus('Conectado');}catch(e){notifyError(e)}finally{cloudBusy=false}}
async function remoteAction(act,args=[],form=null,extra={}){if(cloudBusy)throw Error('Hay otra operación en curso.');cloudBusy=true;cloudStatus('Guardando…');try{const r=await rpc('/action',{act,args,view,form,extra,revision:cloudRev,requestId:uid()});applyRemote(r);cloudStatus('Guardado');if(r.message)toast(r.message);return r}catch(e){cloudStatus(e.message,true);if(e.status===409){setTimeout(()=>refreshCloud(true),0)}if(e.status===401){tokenCloud='';sessionStorage.removeItem(CLOUD_TOKEN);me=null;auth()}throw e}finally{cloudBusy=false}}
function formExtras(action,root){let f={};if(['contentEdit','navPageEdit'].includes(action))f.__blocks=[...root.querySelectorAll('[data-block]')].map(el=>({type:el.querySelector('[data-type]').value,text:el.querySelector('[data-text]').value,url:el.querySelector('[data-url]').value}));if(action==='talentConfig')f.__talents=[...root.querySelectorAll('[data-talent]')].map(el=>({id:uid(),name:el.querySelector('[data-name]').value.trim(),weight:+el.querySelector('[data-weight]').value,description:el.querySelector('[data-desc]').value}));if(action==='conditionsEdit')f.__conditions=[...root.querySelectorAll('[data-cond]')].map(el=>({type:el.querySelector('[name=ctype]').value,ref:el.querySelector('[name=cref]').value,op:el.querySelector('[name=cop]')?.value||'min',min:+(el.querySelector('[name=cmin]')?.value||0)}));if(action==='formulaEdit')f.__formulaKey=root.querySelector('#formula-choice')?.value;return f}
const originalDialogCloud=dialog;
dialog=function(title,body,submit,opts={}){const context=cloudAction?{act:cloudAction.act,args:cloudAction.args.slice()}:null;if(!submit||!context||context.act==='faqEdit')return originalDialogCloud(title,body,submit,opts);return originalDialogCloud(title,body,async(f,form)=>{let extras=formExtras(context.act,form);let result=await remoteAction(context.act,context.args,{...f,...extras});if(context.act==='formEdit'&&context.args[0]==='sheets'&&!context.args[1])setTimeout(showTalent,0);if(context.act==='password'||context.act==='userPassword'){if(context.act==='password'&&me?.temporary)setTimeout(forcePassword,0)}return true},opts)};
