const DIRECT_CLOUD=new Set(['vote','pollVote','drawJoin','potentialPick','spinFor','navDelete','navPageMove','navGroupMove','navMove','categoryMove','categoryDelete','deleteLogs','settingsSave','restore','backup']);
const LOCAL_CLOUD=new Set([...VIEW_ACTIONS,'spinDialog','dataBrowse','selectLogs']);LOCAL_CLOUD.delete('password');LOCAL_CLOUD.delete('bugSubmit');
const localPotential=potentialPick;
potentialPick=function(id,choice){if(choice===undefined){let s=record('sheets',id);if(!s?.potentialChoices?.length)return toast('No hay tiradas pendientes.');return localPotential(id)}return remoteAction('potentialPick',[id,choice]).then(()=>{$('#modal').innerHTML='';render()}).catch(notifyError)};
function deviceInfo(){let ua=navigator.userAgent,browser=/Edg\//.test(ua)?'Edge':/OPR\//.test(ua)?'Opera':/Firefox\//.test(ua)?'Firefox':/Chrome\//.test(ua)?'Chrome':/Safari\//.test(ua)?'Safari':'Otro',os=/Android/.test(ua)?'Android':/Windows/.test(ua)?'Windows':/iPhone|iPad/.test(ua)?'iOS':/Mac OS/.test(ua)?'macOS':/Linux/.test(ua)?'Linux':'Otro';return {id:deviceId,section:view,browser,os,kind:/Mobile|Android/.test(ua)?'Móvil / tableta':'Ordenador',screen:screen.width+' × '+screen.height,zone:Intl.DateTimeFormat().resolvedOptions().timeZone,language:navigator.language}}
let lastHeartbeat=0;
presence=()=>{if(!me||!tokenCloud||Date.now()-lastHeartbeat<Math.max(.1,db.settings.heartbeat||2)*60000-1000)return;lastHeartbeat=Date.now();rpc('/presence',deviceInfo()).catch(e=>{if(e.status===401)notifyError(e)})};
startPresence=()=>{clearInterval(hb);lastHeartbeat=0;presence();hb=setInterval(presence,Math.max(.1,db.settings.heartbeat||2)*60000)};
logout=async()=>{if(cloudBusy)return toast('Espera a que termine el guardado.');try{if(tokenCloud)await rpc('/logout',{device:deviceId})}catch(e){console.warn(e.message)}tokenCloud='';sessionStorage.removeItem(CLOUD_TOKEN);clearInterval(hb);clearInterval(cloudTimer);me=null;$('#modal').innerHTML='';authmode='login';auth()};
forcePassword=()=>originalDialogCloud('Cambiar contraseña temporal',field('Nueva contraseña','password','password','',true)+field('Repetir contraseña','repeat','password','',true),async f=>{if(f.password!==f.repeat)throw Error('Las contraseñas no coinciden.');const r=await rpc('/password',{password:f.password,temporary:true});if(r.token){tokenCloud=r.token;sessionStorage.setItem(CLOUD_TOKEN,tokenCloud)}applyRemote(r);return true},{bind:r=>r.querySelectorAll('[data-close]').forEach(b=>b.remove())});
auth=()=>{applyTheme();const s=cloudAuthInfo||db.settings,reg=authmode==='register';$('#app').innerHTML=`<div class="auth"><div class="card"><div class="brand">${E(s.name||'Dragon Ball Omni Genesis')}</div><div class="tabs"><button id="login" class="${reg?'':'active'}">Iniciar sesión</button>${s.registration!==false?`<button id="register" class="${reg?'active':''}">Registrarse</button>`:''}</div><form id="authform">${field('Usuario','name','text','',true)}${field('Contraseña','password','password','',true)}${reg&&s.invite?field('Código de invitación','code','text','',true):''}<div id="autherr" class="error"></div><button class="primary" style="width:100%">${reg?'Crear cuenta':'Entrar'}</button></form></div></div>`;$('#login').onclick=()=>{authmode='login';auth()};if($('#register'))$('#register').onclick=()=>{authmode='register';auth()};$('#authform').onsubmit=async e=>{e.preventDefault();let b=e.target.querySelector('button');b.disabled=true;try{let f=formValues(e.target),r=await rpc(reg?'/register':'/login',{username:f.name,password:f.password,code:f.code,device:deviceInfo()});tokenCloud=r.token;sessionStorage.setItem(CLOUD_TOKEN,tokenCloud);applyRemote(r);view=firstView();render();startPresence();showTalent();scheduleRefresh();cloudStatus('Conectado')}catch(err){if($('#autherr'))$('#autherr').textContent=err.message}finally{b.disabled=false}}};
function scheduleRefresh(){clearInterval(cloudTimer);cloudTimer=setInterval(()=>refreshCloud(),Math.max(30,db.settings.optimization?.cacheSeconds||120)*1000)}
const baseRemoteDataPage=dataPage;dataPage=()=>{const d=new Date().toISOString().slice(0,10),u=db.serviceUsage?.[d]||{read:0,write:0,delete:0,users:{}};return `<div class="card"><h2>Firestore · operaciones del servicio</h2>${[['read','Lecturas',50000],['write','Escrituras',20000],['delete','Eliminaciones',20000]].map(([k,n,max])=>`<div class="sub"><div class="row"><b>${n}</b><span>${u[k]||0} / ${max.toLocaleString('es-ES')}</span></div><div class="bar"><i style="width:${Math.min(100,(u[k]||0)/max*100)}%"></i></div></div>`).join('')}<h3>Por cuenta</h3>${table(['Cuenta','Lecturas','Escrituras','Eliminaciones'],Object.entries(u.users||{}).map(([id,v])=>[id==='0'?'Sistema':E(userName(+id)),v.read,v.write,v.delete]))}<p class="muted">Operaciones observadas por el servicio; no incluye uso externo y puede perder el tramo de contadores no persistido. Las cifras oficiales están en Firebase.</p></div>`+baseRemoteDataPage()+`<div class="card"><h2>Cloudflare Workers</h2><p>Peticiones registradas por el servicio hoy (UTC): <b>${E(db.workerUsage?.requests??0)}</b> / 100.000</p><div class="bar"><i style="width:${Math.min(100,(db.workerUsage?.requests||0)/1000)}%"></i></div><p class="muted">No equivale a las métricas oficiales de la cuenta. Consulta Analytics en Cloudflare para peticiones, errores y uso de Durable Objects.</p></div>`;};
async function handleRemoteClick(act,args){if(!me||(me.temporary&&act!=='password')||(db.settings.maintenance&&!isOwner()&&!['password','bugSubmit'].includes(act)))return toast('Esta acción no está disponible.');if(!controlAllowed(act,args))return toast('No tienes permiso para esta acción.');if(act==='password'){return originalDialogCloud('Cambiar contraseña',field('Contraseña actual','old','password','',true)+field('Nueva contraseña','password','password','',true)+field('Repetir contraseña','repeat','password','',true),async f=>{if(f.password!==f.repeat)throw Error('Las contraseñas no coinciden.');let r=await rpc('/password',{old:f.old,password:f.password});if(r.token){tokenCloud=r.token;sessionStorage.setItem(CLOUD_TOKEN,tokenCloud)}applyRemote(r);return true})}if(act==='backup'){let r=await rpc('/backup');let blob=new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='omni-genesis-'+now().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(act==='restore'){let file=$('#restorefile')?.files[0];if(!file)return toast('Selecciona un archivo.');if(!confirm('¿Restaurar la copia de seguridad?'))return;let r=await rpc('/restore',{backup:JSON.parse(await file.text()),revision:cloudRev});if(r.token){tokenCloud=r.token;sessionStorage.setItem(CLOUD_TOKEN,tokenCloud)}applyRemote(r);render();toast('Copia restaurada.');return}if(act==='potentialPick')return potentialPick(...args);if(act==='settingsSave'){let form=$('#settingsform');if(!form.reportValidity())return;await remoteAction(act,args,formValues(form));render();return}if(act==='deleteLogs'){let ids=args[0]?null:[...document.querySelectorAll('.logsel:checked')].map(x=>x.value);if(ids&&!ids.length)return toast('Selecciona registros.');if(!confirm('¿Eliminar definitivamente los registros?'))return;await remoteAction(act,args,null,{ids});render();return}if(act==='spinFor'){let b=document.querySelector('[data-act=spinFor]');if(b)b.disabled=true;try{let r=await remoteAction(act,args);let wheel=$('#wheel'),el=$('#spinresult');if(wheel&&el){wheel.classList.add('spin');setTimeout(()=>{el.innerHTML=`<h2>${E(r.spin?.name||'Resultado guardado')}</h2><p>${E(r.spin?.rarity||'')} · ${r.spin?.pending?'Pendiente de revisión':'Añadido al inventario'}</p>`;if(b)b.disabled=false},850)}else render()}catch(e){if(b)b.disabled=false;throw e}return}if(act==='remove'&&['pages','announcements'].includes(args[0])){if(!confirm('¿Eliminar definitivamente?'))return;await remoteAction(act,args);render();return}if(DIRECT_CLOUD.has(act)){if(['navDelete','categoryDelete'].includes(act)&&!confirm('¿Eliminar?'))return;await remoteAction(act,args);render();return}if(LOCAL_CLOUD.has(act)){handlers[act]?.(...args);return}const h=handlers[act];if(!h)return;cloudAction={act,args};try{h(...args)}finally{cloudAction=null}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();let args;try{args=JSON.parse(b.dataset.args||'[]')}catch{return toast('Acción inválida.')}Promise.resolve(handleRemoteClick(b.dataset.act,args)).catch(notifyError)});
document.addEventListener('click',e=>{let b=e.target.closest('[data-faq-nav]');if(b){e.preventDefault();if(b.dataset.faqNav==='@bug')handleRemoteClick('bugSubmit',[]).catch(notifyError);else faqNavigate(b.dataset.faqNav)}});
(async()=>{auth();try{cloudAuthInfo=await rpc('/health');if(!tokenCloud){auth();cloudStatus('Conectado');return}await refreshCloud(true);if(me){startPresence();scheduleRefresh();showTalent()}}catch(e){cloudStatus(e.message,true);if($('#autherr'))$('#autherr').textContent=e.message}})();
window.addEventListener('focus',()=>refreshCloud());
